window.VADE_DRUGS=[{"id":"aas","name":"Ácido acetilsalicílico (AAS)","brand":"Adiro / Aspirina / EFG","group":"Hemostasia y fibrinólisis","routes":"VO, IV según producto","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Antiagregación plaquetaria en síndrome coronario agudo y prevención secundaria cardiovascular según contexto; analgesia/antipiresis con otras presentaciones y dosis.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"acido_tranexamico","name":"Ácido tranexámico","brand":"Amchafibrin","group":"Hemostasia y fibrinólisis","routes":"IV, VO","reviewed":true,"presentation":"Amchafibrin 500 mg/5 ml (100 mg/ml); otras presentaciones según FT.","indication":"Tratamiento de sangrados por fibrinólisis excesiva; aplicación concreta según cirugía, trauma o cuadro clínico.","contraindication":"Trombosis arterial o venosa aguda, insuficiencia renal grave, antecedentes de convulsiones o hipersensibilidad, según presentación y ficha técnica; revisar excepciones por indicación.","precautions":"Requiere ajuste por función renal; riesgo de convulsiones a dosis elevadas y de eventos trombóticos en pacientes predispuestos.","adverse":"Náuseas, hipotensión si IV demasiado rápida, convulsiones e hipersensibilidad.","administration":"Inyección IV lenta, no más rápida de 1 ml/min para el preparado de 100 mg/ml.","dosing":"Dosis de referencia en fibrinólisis sistémica: 1 g cada 6–8 h; individualizar por indicación y función renal.\nNo extrapolar pautas de hemorragia traumática o posparto a otras indicaciones. La calculadora universal solo convierte una pauta prescrita.","sources":[["Ficha técnica Amchafibrin inyectable (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/53939/FichaTecnica_53939.html"]],"notes":"Comprueba si la indicación concreta tiene protocolo propio.","dosingBrief":"Fibrinólisis sistémica: 1 g IV cada 6–8 h; ajustar según indicación y función renal.","kineticsReviewed":false,"diluent":"Puede administrarse IV lento sin diluir; para perfusión diluir según la ficha del producto y protocolo."},{"id":"valproato","name":"Ácido valproico","brand":"Depakine (presentaciones según FT)","group":"Neurología y reversión","routes":"IV, VO","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Tratamiento de crisis epilépticas y estados epilépticos seleccionados; profilaxis de migraña y episodios maníacos con formulaciones apropiadas y restricciones específicas (especialmente embarazo).","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Pendiente: el esquema de estatus epiléptico debe cotejarse con protocolos actuales y función hepática.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"zoledronato","name":"Ácido zoledrónico","brand":"Zometa / Aclasta / EFG (según indicación)","group":"Metabolismo y otros","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Tratamiento de hipercalcemia maligna, acontecimientos óseos en neoplasias, osteoporosis y enfermedad de Paget según formulación y pauta autorizadas.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Pendiente: distintas presentaciones y dosis para hipercalcemia tumoral y osteoporosis; controlar ClCr, hidratación y calcio.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"adenosina","name":"Adenosina","brand":"Adenocor","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Adenocor 6 mg/2 ml (3 mg/ml).","indication":"Taquicardia supraventricular regular dependiente del nodo AV en paciente estable, tras maniobras vagales. Uso diagnóstico en casos seleccionados.","contraindication":"Bloqueo AV 2.º/3.º o enfermedad del seno sin marcapasos, broncoespasmo (asma/EPOC con broncoespasmo), QT largo, hipotensión grave, IC descompensada.","precautions":"Uso hospitalario con ECG continuo y medios de reanimación. Precaución en preexcitación y taquicardias irregulares; comprobar interacciones.","adverse":"Rubor, opresión torácica, disnea, bradicardia, bloqueo AV transitorio y broncoespasmo.","administration":"Bolo IV muy rápido por vía proximal seguido de lavado rápido con SF.","dosing":"Secuencia IV rápida seleccionada de 6 mg y, si precisa, 12 mg, seguida de lavado con SF. No usar en FA preexcitada ni taquicardia irregular de QRS ancho.","sources":[["AEMPS · Adenocor","https://cima.aemps.es/cima/dochtml/ft/60375/FT_60375.htm"],["ERC 2025 · ALS","https://www.erc.edu/media/vedoa2ga/gl2025-05-als-e.pdf"]],"notes":"La secuencia seleccionada es 6 → 12 mg y no incluye dosis superiores automáticas; existen pautas diferentes según fuentes y presentación.","dosingBrief":"Taquicardia supraventricular regular: 6 mg IV rápido y, si persiste tras 1–2 min, 12 mg IV rápido. Lavado inmediato con SF 0,9 %.","kineticsReviewed":true,"clinicalKinetics":"Semivida plasmática de segundos (<10 s). Efecto transitorio, con recuperación rápida del nodo AV.","special":{"kind":"dose_cards","cards":[{"title":"Primera dosis","subtitle":"6 mg IV muy rápido","copy":"Adenosina 6 mg IV en bolo muy rápido por vía proximal, seguida inmediatamente de lavado rápido con SF 0,9 %. Monitorización ECG continua."},{"title":"Segunda dosis (si persiste tras 1–2 minutos)","subtitle":"12 mg IV muy rápido","copy":"Adenosina 12 mg IV en bolo muy rápido por vía proximal, seguida inmediatamente de lavado rápido con SF 0,9 %. Monitorización ECG continua."}],"sections":[{"title":"Vía y condiciones","text":"Bolo IV muy rápido por vía proximal, seguido inmediatamente de lavado rápido de SF 0,9 %. ECG continuo y equipo de reanimación disponible."},{"title":"Precauciones","text":"Evitar en FA con preexcitación o taquicardias irregulares; riesgo de broncoespasmo, bloqueo AV y pausas. Revisar interacciones con dipiridamol y metilxantinas."},{"title":"Farmacocinética clínica","text":"Semivida muy corta, inferior a 10 segundos. Inicio y desaparición del efecto en segundos."}]},"diluent":"Bolo IV rápido sin diluir, seguido de lavado inmediato con SF 0,9 %."},{"id":"adrenalina","name":"Adrenalina","brand":"Adrenalina B. Braun","group":"Arritmias y cardiovascular","routes":"IM, IV/IO (RCP), perfusión IV","reviewed":true,"presentation":"Adrenalina B. Braun 1 mg/ml; ampolla 1 mg/1 ml.","indication":"Anafilaxia; parada cardíaca; shock anafiláctico refractario (perfusión por equipo experimentado).","contraindication":"En anafilaxia potencialmente mortal, no existen contraindicaciones absolutas para la administración IM. Evitar errores de concentración y vía.","precautions":"No administrar 1 mg IV en bolo a un paciente con circulación espontánea por anafilaxia. Riesgo de arritmias, hipertensión, isquemia y extravasación en perfusión.","adverse":"Taquicardia, temblor, palpitaciones, arritmias, hipertensión e isquemia.","administration":"IM sin diluir en anafilaxia. RCP IV/IO con dilución a 0,1 mg/ml (1 mg/10 ml finales). Perfusión continua exclusivamente con bomba y monitorización.","dosing":"Anafilaxia en adultos: adrenalina 0,5 mg IM en cara anterolateral del muslo y repetir si persisten síntomas respiratorios o circulatorios a los 5 minutos.\nParada cardíaca en adultos: 1 mg IV/IO cada 3–5 minutos; tras tercera descarga en ritmo desfibrilable o tan pronto como sea posible en no desfibrilable. Preparación 1 mg en 10 ml finales (0,1 mg/ml).\nSi la anafilaxia es refractaria, considerar perfusión IV por personal experimentado; inicio orientativo 0,1 µg/kg/min, con titulación individualizada.","sources":[["AEMPS · Adrenalina B. Braun","https://cima.aemps.es/cima/dochtml/ft/68552/FichaTecnica_68552.html"],["ERC 2025 · Situaciones especiales (anafilaxia)","https://www.erc.edu/media/wwufbysp/gl2025-06-spec-circ-e.pdf"],["ERC 2025 · Soporte vital avanzado","https://www.erc.edu/media/vedoa2ga/gl2025-05-als-e.pdf"]],"notes":"La dosis de 1 mg IV/IO corresponde a la parada cardíaca. Las diluciones de perfusión solicitadas deben contrastarse con Farmacia/protocolo local antes del uso.","dosingBrief":"Anafilaxia: 0,5 mg IM (0,5 ml) en muslo; repetir a los 5 min si persisten síntomas graves.\nRCP: 1 mg IV/IO cada 3–5 min (dilución 0,1 mg/ml).\nShock anafiláctico refractario: perfusión IV titulada desde 0,1 µg/kg/min en entorno monitorizado.","special":{"kind":"weight","doses":[0.05,0.1,0.15,0.2,0.3,0.4,0.5],"decimals":1,"preparations":[{"id":"adre_3_250","label":"3 mg en 250 ml · 12 µg/ml","amountMg":3,"volumeMl":250,"name":"3 mg en 250 ml finales de SG 5 % o SF 0,9 %","detail":"3 ampollas de 1 mg/1 ml; completar hasta 250 ml finales."},{"id":"adre_2_100","label":"2 mg en 100 ml · 20 µg/ml","amountMg":2,"volumeMl":100,"name":"2 mg en 100 ml finales de SG 5 % o SF 0,9 %","detail":"2 ampollas de 1 mg/1 ml; completar hasta 100 ml finales."}],"sections":[{"title":"Indicaciones y seguridad","text":"La perfusión se reserva a anafilaxia refractaria bajo personal experimentado y monitorización continua. No sustituye la primera dosis IM. No confundir con bolo IV de RCP; la perfusión no justifica administrar 1 mg IV en bolo en pacientes con pulso."},{"title":"Vía, vigilancia y precauciones","text":"Administración mediante bomba, vía adecuada y ECG/PA continuos; vigilar acceso vascular, isquemia y extravasación. Titular según respuesta clínica y hemodinámica."},{"title":"Interacciones","text":"Precaución con IMAO, antidepresivos tricíclicos y otros simpaticomiméticos; pueden aumentar la respuesta cardiovascular."},{"title":"Farmacocinética clínica","text":"Efecto IV prácticamente inmediato; IM en pocos minutos. Semivida plasmática de pocos minutos y acción clínica breve; reevaluar y titular según respuesta."}]},"copyPautas":[{"title":"Anafilaxia · IM","text":"Adrenalina 0,5 mg (0,5 ml de 1 mg/ml) IM en cara anterolateral del muslo. Repetir a los 5 min si persisten síntomas respiratorios o circulatorios."},{"title":"RCP · IV/IO","text":"Adrenalina 1 mg IV/IO cada 3–5 min durante RCP; diluir 1 mg de la ampolla de 1 mg/ml hasta 10 ml finales (0,1 mg/ml)."}],"clinicalKinetics":"Efecto IV prácticamente inmediato; IM en pocos minutos. Semivida plasmática de pocos minutos y acción clínica breve; reevaluar y titular según respuesta.","kineticsReviewed":true,"mechanism":"Agonista adrenérgico α₁, β₁ y β₂.","diluent":"Perfusión: SG 5 % o SF 0,9 % según preparación. Anafilaxia IM sin diluir; RCP IV/IO: dilución específica."},{"id":"alteplasa","name":"Alteplasa","brand":"Actilyse","group":"Hemostasia y fibrinólisis","routes":"IV","reviewed":true,"presentation":"Actilyse, polvo y disolvente IV (presentaciones según indicación).","indication":"Trombólisis en patologías específicas (ictus isquémico, TEP de alto riesgo e IAM, con protocolos diferentes).","contraindication":"Riesgo de hemorragia, sangrado activo, contraindicaciones neurológicas/vasculares específicas según indicación.","precautions":"Uso en circuito de trombólisis con criterios de elegibilidad, imagen/monitorización y control de hemorragias.","adverse":"Hemorragia intracraneal y sistémica, angioedema y reacciones de hipersensibilidad.","administration":"Administración IV según indicación. NO utilizar la pauta de ictus para TEP o IAM.","dosing":"Ictus isquémico adulto según FT: 0,9 mg/kg (máximo 90 mg), 10% en bolo IV y resto en 60 min. El resto de indicaciones se mantienen pendientes de revisión individual.","sources":[["Ficha técnica Actilyse (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/59494/FT_59494.html"]],"notes":"Calculadora dedicada de ICTUS; TEP/IAM requieren pauta y selección independientes.","dosingBrief":"Ictus isquémico: 0,9 mg/kg IV (máx. 90 mg); 10% bolo y resto en 60 min.","kineticsReviewed":false,"diluent":"Reconstituir con el disolvente específico suministrado; concentración y preparación posteriores dependen de la presentación y la indicación (ictus/TEP/IAM)."},{"id":"amiodarona","name":"Amiodarona","brand":"Trangorex","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Trangorex 150 mg/3 ml (50 mg/ml), ampolla para IV.","indication":"Taquicardia ventricular y arritmias supraventriculares seleccionadas, especialmente cuando otros antiarrítmicos no son apropiados; FV/TV sin pulso refractaria a desfibrilación en reanimación (dosis distintas).","contraindication":"Hipersensibilidad a amiodarona, yodo o excipientes; consultar restricciones por bradicardia, bloqueos y alteraciones tiroideas, con excepciones en reanimación.","precautions":"Hipotensión y bradicardia IV, trastorno de conducción, prolongación QT e interacciones. Evitar en FA preexcitada. Control tiroideo y hepático si tratamiento continuado.","adverse":"Hipotensión y colapso si se administra rápido, bradicardia, proarritmia y lesión local/flebitis.","administration":"Exclusivamente SG 5 %. Volúmenes de preparación finales. Perfusión preferentemente por acceso central, monitorización ECG/PA. No confundir pauta de perfusión en taquiarritmias con el bolo de RCP.","dosing":"Carga IV seleccionada: 300 mg/250 ml finales de SG 5 % en 30–60 min; alternativa ajustada al peso 5 mg/kg/250 ml SG 5 % en 20–120 min.\nPauta secuencial IV seleccionada para esta herramienta: 600 mg/250 ml SG 5 % en 12 h, seguida de 600 mg/250 ml SG 5 % en 24 h (esquema aportado por el usuario; no es idéntico al mantenimiento ESC).\nFV/TV sin pulso: 300 mg IV/IO tras tercera descarga y 150 mg más tras quinta descarga.\nTransición oral: considerar 200 mg cada 8 horas como pauta orientativa de carga desde el primer día, solo tras valoración individual y contabilizando la dosis IV acumulada.","sources":[["Ficha técnica Trangorex (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/54723/FT_54723.html"],["ESC 2024 · Fibrilación auricular","https://academic.oup.com/eurheartj/article/45/36/3314/7738779"],["AEMPS · Trangorex","https://cima.aemps.es/cima/dochtml/ft/54723/FichaTecnica_54723.html"],["ERC 2025 · Soporte vital avanzado","https://www.erc.edu/media/vedoa2ga/gl2025-05-als-e.pdf"]],"notes":"Carga preferente de 300 mg/250 ml. El mantenimiento secuencial seleccionado requiere cotejo con el protocolo asistencial y contabilizar la carga total.","dosingBrief":"Taquiarritmia con pulso: 300 mg IV en 250 ml finales de SG 5 % durante 60 min. Mantenimiento secuencial: 600 mg/250 ml en 12 h, después 600 mg/250 ml en 24 h. En FV/TV sin pulso: 300 mg IV/IO tras tercera descarga y 150 mg tras quinta. Continuación VO solo si indicada.","special":{"kind":"amiodarone","sections":[{"title":"Vía y administración","text":"Diluir exclusivamente con SG 5 %. Infusión preferentemente por vía central, con monitorización ECG y PA. Administración IV rápida y dosificación en RCP obedecen a un protocolo distinto."},{"title":"Precauciones y contraindicaciones","text":"Hipotensión, bradicardia, bloqueo AV, prolongación QT, interacciones y toxicidad tiroidea, hepática y pulmonar. Evitar en fibrilación auricular preexcitada. Si inestabilidad hemodinámica por arritmia, valorar cardioversión sincronizada."},{"title":"Monitorización","text":"ECG, ritmo, FC y PA durante la perfusión; vigilar función tiroidea y hepática para tratamiento continuado."},{"title":"Interacciones","text":"Digoxina, antagonistas vitamina K, betabloqueantes, otros bradicardizantes y fármacos que prolongan QT."},{"title":"Ajustes","text":"No suele requerir ajuste renal; cautela por disfunción hepática y toxicidad acumulativa."},{"title":"Farmacocinética clínica","text":"Tras perfusión IV el efecto se inicia en minutos, pero la cardioversión de FA puede tardar 8–12 horas o días. Semivida terminal muy larga (semanas): persistencia de interacciones y toxicidad tras la retirada."}]},"copyPautas":[],"clinicalKinetics":"Tras perfusión IV el efecto se inicia en minutos, pero la cardioversión de FA puede tardar 8–12 horas o días. Semivida terminal muy larga (semanas): persistencia de interacciones y toxicidad tras la retirada.","kineticsReviewed":true,"sourcesNotes":"La preparación de 300 mg/250 ml para carga coincide con la pauta ESC 2024; el esquema secuencial de 600 mg/250 ml durante 12 h y después 24 h procede del esquema práctico facilitado y no es idéntico a 900–1.200 mg/24 h de ESC. Verificar pauta local.","diluent":"SG 5 % exclusivamente.","doseRows":[{"title":"Taquiarritmia con pulso · carga","text":"300 mg en 250 ml finales de SG 5 %, durante 60 min.","copy":"Amiodarona 300 mg IV en 250 ml finales de SG 5 %, durante 60 min (250 ml/h)."},{"title":"Mantenimiento · primeras 12 h","text":"600 mg en 250 ml finales de SG 5 %, durante 12 h.","copy":"Amiodarona 600 mg IV en 250 ml finales de SG 5 %, durante 12 h (20,8 ml/h)."},{"title":"Mantenimiento · siguientes 24 h","text":"600 mg en 250 ml finales de SG 5 %, durante 24 h.","copy":"Amiodarona 600 mg IV en 250 ml finales de SG 5 %, durante 24 h (10,4 ml/h)."},{"title":"FV/TV sin pulso · reanimación","text":"300 mg IV/IO tras la tercera descarga; 150 mg adicionales tras la quinta si persiste."}]},{"id":"atropina","name":"Atropina","brand":"Atropina B. Braun / Noridem","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Atropina 1 mg/ml, ampolla de 1 ml (presentación seleccionada).","indication":"Bradicardia sintomática con compromiso hemodinámico e intoxicación por organofosforados/anticolinesterásicos.","contraindication":"En emergencia vital, las contraindicaciones habituales deben ponderarse frente a la necesidad de tratamiento. Para usos no urgentes: consultar FT por hipersensibilidad y enfermedades en las que el efecto antimuscarínico esté contraindicado.","precautions":"En trasplante cardíaco puede desencadenar efectos paradójicos; en BAV infranodal/QRS ancho puede ser ineficaz. Vigilar taquiarritmias, isquemia, retención urinaria, íleo y glaucoma de ángulo cerrado.","adverse":"Taquicardia, sequedad de mucosas, retención urinaria, confusión/anticolinergia.","administration":"Inyección IV; confirmar concentración de la ampolla. En intoxicaciones graves puede precisarse perfusión posterior conforme a toxicología/protocolo.","dosing":"Bradicardia con signos adversos: 0,5 mg IV cada 3–5 min hasta 3 mg acumulados. Evitar en trasplante cardíaco y bloqueo AV de alto grado con QRS ancho; no retrasar estimulación eléctrica si está indicada.\nIntoxicación grave por organofosforados: 1–2 mg IV de inicio; reevaluar cada 5 min y considerar duplicación sucesiva hasta controlar broncorrea, broncoespasmo y compromiso hemodinámico. El límite de 3 mg de bradicardia NO se aplica a intoxicación grave.","sources":[["AEMPS · Atropina B. Braun 1 mg/ml","https://cima.aemps.es/cima/dochtml/ft/27535/FT_27535.html"],["AEMPS · Atropina Noridem 1 mg/ml","https://cima.aemps.es/cima/dochtml/ft/90370/FT_90370.html"],["ERC 2025 · Soporte vital avanzado","https://www.erc.edu/media/vedoa2ga/gl2025-05-als-e.pdf"],["AHA 2025 · Dosis alternativa bradicardia 1 mg IV","https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-advanced-life-support"]],"notes":"El máximo de 3 mg corresponde a la bradicardia; no limita la dosis acumulada necesaria en intoxicación anticolinesterásica grave.","dosingBrief":"Bradicardia sintomática: 0,5 mg IV; repetir cada 3–5 min (máximo acumulado 3 mg).\nOrganofosforados: inicio 1–2 mg IV y repetir/duplicar cada ~5 min según respuesta; sin máximo fijo en esta indicación.","special":{"kind":"none","sections":[{"title":"Contraindicaciones y precauciones","text":"En trasplante cardíaco se debe evitar; puede producir bloqueo AV grave o asistolia. No emplear en bloqueo AV alto grado con QRS ancho como sustituto de marcapasos. Precaución en cardiopatía isquémica, taquiarritmias, retención urinaria y glaucoma de ángulo cerrado."},{"title":"Intoxicación por organofosforados","text":"La pauta de 1–2 mg IV con escalada/duplicación aproximada cada 5 minutos es una estrategia de atropinización para cuadros graves; difiere de los intervalos de repetición de algunas fichas técnicas. Titular hasta controlar broncorrea, broncoespasmo y compromiso circulatorio. Considerar oximas según tóxico."},{"title":"Interacciones","text":"Efectos anticolinérgicos aditivos con tricíclicos (amitriptilina), antihistamínicos sedantes (hidroxicina) y otros antimuscarínicos."},{"title":"Farmacocinética clínica","text":"Efecto cronotrópico IV rápido, máximo orientativo a los 2–4 minutos. Semivida de eliminación aproximada de 4 horas; la duración de la acción varía según el efecto evaluado."}]},"copyPautas":[],"clinicalKinetics":"Efecto cronotrópico IV rápido, máximo orientativo a los 2–4 minutos. Semivida de eliminación aproximada de 4 horas; la duración de la acción varía según el efecto evaluado.","kineticsReviewed":true,"sourcesNotes":"Para bradicardia se prioriza ERC 2025 (0,5 mg IV); AHA 2025 utiliza 1 mg IV. En intoxicación, la duplicación cada 5 min es una estrategia de intoxicación grave diferente de los intervalos de repetición de algunas fichas técnicas.","diluent":"Bolo IV sin dilución obligatoria para la presentación indicada.","doseRows":[{"title":"Bradicardia con compromiso","text":"0,5 mg IV; repetir cada 3–5 min hasta un máximo de 3 mg."},{"title":"Intoxicación colinérgica","text":"1–2 mg IV iniciales; duplicar aproximadamente cada 5 min según signos de atropinización, sin máximo de 3 mg."}]},{"id":"bicarbonato_1m","name":"Bicarbonato sódico 1 M","brand":"Venofusin Bicarbonato sódico 1 M","group":"Electrolitos y soluciones","routes":"IV","reviewed":true,"presentation":"Solución 1 M (8,4%): 1 mmol = 1 mEq de bicarbonato y de sodio por ml; 250 ml contienen 250 mmol.","indication":"Acidosis metabólica grave seleccionada o alcalinización urinaria en intoxicaciones concretas; usar según contexto clínico y protocolo.","contraindication":"Revisar la ficha técnica de la presentación ante alcalosis metabólica/respiratoria y otras restricciones. La hipernatremia o hipocalcemia requieren valoración específica; no equiparar automáticamente a contraindicación absoluta.","precautions":"Solución hipertónica (2.000 mOsm/l). Riesgo de sobrecarga de sodio/volumen, alcalosis, trastornos de K/Ca y lesión por extravasación; para solución hipertónica se indica vía central en FT.","adverse":"Alcalosis, hipernatremia, hipopotasemia, hipocalcemia, sobrecarga de volumen, necrosis por extravasación.","administration":"Habitualmente perfusión IV diluida hasta isotonicidad según compatibilidad; la FT también describe administración lenta en situaciones específicas. Titular con gasometría y electrolitos.","dosing":"La FT recomienda individualizar según estado ácido-base y corregir inicialmente, como máximo, alrededor de la mitad del déficit calculado, con reevaluación frecuente. La indicación, dilución, vía y velocidad requieren protocolo clínico. Para solución hipertónica, la FT indica vía central.","dosingBrief":"1 M = 1 mEq/ml. Dosis individualizada por déficit y gasometría; no usar una pauta fija sin monitorización.","sources":[["Ficha técnica Venofusin Bicarbonato sódico 1 M (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/49811/FT_49811.html"]],"notes":"No confundir con 1/6 M (167 mmol/l). Confirmar vía, dilución y protocolos del hospital.","kineticsReviewed":false,"diluent":"Diluir según indicación y osmolaridad; comprobar solución compatible, no predeterminar una sola preparación."},{"id":"bicarbonato_1_6m","name":"Bicarbonato sódico 1/6 M","brand":"Bicarbonato sódico 1/6 M Braun","group":"Electrolitos y soluciones","routes":"IV","reviewed":true,"presentation":"Solución 1/6 M: 167 mmol/l de bicarbonato y de sodio (= 0,167 mEq/ml). Bolsa de 250 ml: ~41,75 mmol.","indication":"Acidosis metabólica grave seleccionada o alcalinización urinaria en intoxicaciones concretas, según protocolo.","contraindication":"Consultar ficha técnica de la presentación ante alcalosis y otras contraindicaciones específicas; separar los riesgos de carga de sodio y sobrecarga de volumen como precauciones.","precautions":"Aporte simultáneo de sodio y bicarbonato. Monitorizar gasometría, sodio, potasio, calcio y balance hídrico; vigilar extravasación.","adverse":"Alcalosis, alteraciones hidroelectrolíticas, sobrecarga de volumen y reacciones locales.","administration":"Solución para perfusión IV. La dosis y velocidad se ajustan a situación clínica y determinaciones seriadas; no equiparar volumen con bicarbonato 1 M.","dosing":"Individualizar a partir de intensidad de acidosis y gasometría. La FT recomienda no corregir de entrada más del 50% del déficit estimado, revalorando gasometría y estado clínico durante el tratamiento.","dosingBrief":"1/6 M = 0,167 mEq/ml (250 ml ≈ 41,75 mEq). Perfusión IV; ajustar según gasometría y protocolo.","sources":[["Ficha técnica Bicarbonato sódico 1/6 M Braun (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/47517/FichaTecnica_47517.html"]],"notes":"No confundir con 1 M (1 mEq/ml). Una misma cantidad de mEq exige aproximadamente seis veces más volumen con 1/6 M.","kineticsReviewed":false,"diluent":"Solución preparada para perfusión; no confundir con el concentrado 1 M."},{"id":"clevidipino","name":"Clevidipino","brand":"Cleviprex","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Cleviprex 0,5 mg/ml emulsión; viales de 50 ml (25 mg) y 100 ml (50 mg).","indication":"Reducción rápida de presión arterial en ámbito PERIOPERATORIO (indicación en FT española).","contraindication":"Hipersensibilidad a soja/cacahuete/huevo, trastornos del metabolismo lipídico y estenosis aórtica grave.","precautions":"Lípidos, técnica aséptica, TA/FC de forma continua, hipotensión y taquicardia refleja. No inferir autorización para urgencias hipertensivas generales.","adverse":"Hipotensión, taquicardia refleja, náuseas, edema y complicaciones de emulsión lipídica.","administration":"LISTO PARA USAR: no diluir. Perfusión IV por bomba, periférica o central; no administrar con otros medicamentos en la misma línea. Descartar a las 12 h tras perforación según FT.","dosing":"FT: dosis inicial 2 mg/h (4 ml/h); titulaciones posteriores según respuesta; muchos pacientes requieren 4–6 mg/h (8–12 ml/h).","sources":[["Ficha técnica Cleviprex (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/76595/FichaTecnica_76595.html"]],"notes":"NO es una indicación genérica de tratamiento de emergencia hipertensiva en España; FT: perioperatorio.","dosingBrief":"Perfusión IV: inicio 2 mg/h (4 ml/h); titular según respuesta y protocolo.","kineticsReviewed":false,"mechanism":"Calcioantagonista dihidropiridínico de acción ultracorta.","diluent":"Emulsión lipídica lista para uso: NO diluir."},{"id":"clopidogrel","name":"Clopidogrel","brand":"Plavix / EFG","group":"Hemostasia y fibrinólisis","routes":"VO","reviewed":true,"presentation":"Plavix / EFG, 75 mg y comprimido de 300 mg para carga.","indication":"Antiagregación, en particular SCA; la pauta depende de reperfusión/ICP y contexto.","contraindication":"Hemorragia patológica activa o insuficiencia hepática grave; comprobar ficha.","precautions":"Riesgo hemorrágico, interacciones CYP2C19 y tratamiento combinado.","adverse":"Hemorragia y reacciones cutáneas; raramente púrpura trombótica trombocitopénica.","administration":"Vía oral. En SCASEST: carga 300 mg o 600 mg según estrategia y circunstancias; mantenimiento 75 mg/24 h. Las restricciones difieren por edad y reperfusión.","dosing":"Carga 300–600 mg en SCA según indicación; mantenimiento 75 mg/24 h. Confirmar selección con protocolo de cardiología.","sources":[["Ficha técnica Plavix 300 mg (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/98069009/FT_98069009.html"]],"notes":"La carga depende de tipo de SCA, edad y estrategia invasiva.","dosingBrief":"SCA: carga 300–600 mg VO; mantenimiento 75 mg/24 h según indicación.","kineticsReviewed":false},{"id":"cloruro_calcico","name":"Cloruro cálcico","brand":"Cloruro de calcio Braun","group":"Electrolitos y reposición","routes":"IV","reviewed":true,"presentation":"Cloruro cálcico 100 mg/ml (hexahidrato). Ampolla de 10 ml = 1 g; 9,13 mEq = 4,565 mmol de Ca²⁺.","indication":"Hipocalcemia cuando se necesita elevación rápida de calcio sérico; coadyuvante en hiperpotasemia, intoxicación por magnesio y ciertas emergencias en reanimación conforme a protocolo.","dosingBrief":"Dosis y velocidad según indicación y ECG; 10 ml aportan 4,565 mmol de calcio. No es intercambiable por volumen con gluconato cálcico.","dosing":"Administrar con especial control de vía por riesgo de necrosis; la ficha técnica histórica contiene pautas de reanimación que deben contrastarse con guías actualizadas.","administration":"Inyección IV lenta en vía central preferente para evitar lesión por extravasación; control ECG y del acceso.","diluent":"IV lento según ficha; para perfusión diluida confirmar diluyente y concentración con Farmacia.","contraindication":"Hipercalcemia, riesgo de arritmias y otros supuestos según ficha específica.","precautions":"Riesgo elevado de necrosis por extravasación; vigilar ritmo y calcio, precaución con digitálicos. Incompatible con soluciones de fosfatos en mezclas no validadas.","adverse":"Bradicardia, arritmias, hipercalcemia y necrosis local.","sources":[["AEMPS · Cloruro cálcico Braun","https://cima.aemps.es/cima/dochtml/ft/49072/FT_49072.html"]],"notes":"Preferir acceso venoso central para concentraciones elevadas; el medicamento NO es equivalente en calcio al gluconato."},{"id":"cloruro_sodico","name":"Cloruro sódico hipertónico","brand":"NaCl 3% / concentrados para preparación","group":"Electrolitos y soluciones","routes":"IV","reviewed":true,"presentation":"NaCl 3%: 3 g/100 ml, aproximadamente 513 mmol (mEq) de sodio por litro. Concentrados para preparación: verificar composición exacta.","indication":"Hiponatremia sintomática grave, siempre con diagnóstico y monitorización apropiados.","contraindication":"No es tratamiento indiscriminado de cualquier hiponatremia; valorar riesgo de sobrecorrección y situación clínica.","precautions":"Na sérico seriado, volumen/diuresis y riesgo de desmielinización osmótica. Consultar protocolo local de preparación y doble comprobación.","adverse":"Hipernatremia, sobrecorrección, sobrecarga de volumen y lesión local.","administration":"Guía europea: para síntomas graves recomienda bolos de 150 ml de NaCl 3% durante 20 min, reevaluando sodio y clínica. Se debe emplear solución preparada/validada por Farmacia.","dosing":"150 ml de NaCl 3% contienen aproximadamente 77 mmol de sodio y en 20 minutos equivalen aritméticamente a 450 ml/h; esto NO es una predicción de cuánto aumentará la natremia.","sources":[["Guía europea de hiponatremia","https://academic.oup.com/ejendo/article/170/3/G1/6668028"]],"notes":"No usar fórmulas de déficit de sodio como sustituto de control analítico seriado.","dosingBrief":"NaCl al 3%: 150 ml en 20 min como pauta de referencia para hiponatremia sintomática grave; reevaluar según protocolo.","kineticsReviewed":false,"diluent":"Administrar una solución de NaCl 3 % lista para usar o preparación validada por Farmacia."},{"id":"digoxina","name":"Digoxina","brand":"Digoxina Kern Pharma","group":"Arritmias y cardiovascular","routes":"IV, VO","reviewed":true,"presentation":"Ampolla 0,5 mg/2 ml (0,25 mg/ml); comprimido 0,25 mg.","indication":"Control de frecuencia ventricular en fibrilación auricular/flutter en situaciones seleccionadas y tratamiento de IC crónica sintomática en casos indicados.","contraindication":"Bloqueos AV avanzados sin marcapasos, arritmias ventriculares por digital, intoxicación digitálica y FA preexcitada; consultar FT.","precautions":"Margen terapéutico estrecho; ajustar a función renal, edad, masa magra, potasio y magnesio. Interacciones con amiodarona, verapamilo y otros inhibidores de P-gp.","adverse":"Bradiarritmia, bloqueo AV, arritmias, náuseas, alteraciones visuales y síntomas de intoxicación.","administration":"IV lentamente según ficha técnica; vigilar respuesta y función renal. La necesidad de continuar VO tras un episodio agudo se individualiza.","dosing":"No convertir la carga en una suma automática: revalorar antes de dosis adicionales. Carga oral individualizada 0,75–1,5 mg en fracciones según FT; mantenimiento oral generalmente 0,0625–0,25 mg al día, en particular menor en ancianos/insuficiencia renal.","sources":[["AEMPS · Digoxina Kern Pharma","https://cima.aemps.es/cima/dochtml/ft/34753/FT_34753.htm"],["ESC 2024 · Fibrilación auricular","https://academic.oup.com/eurheartj/article/45/36/3314/7738779"]],"notes":"La dosis total de carga depende del contexto y función renal. No repetir ciegamente dosis IV. Fraccionamiento oral de comprimidos según presentación disponible.","kineticsReviewed":true,"dosingBrief":"Carga IV individualizada: 0,5 mg inicial; valorar dosis adicionales de 0,25 mg tras 4–8 horas según respuesta (total parenteral 0,5–1 mg). Mantenimiento VO habitual 0,0625–0,25 mg/24 h según edad, función renal y niveles.","clinicalKinetics":"IV: inicio aproximadamente 5–30 min y máximo efecto clínico en 1–5 h. VO: inicio 30–120 min y máximo 2–6 h. Semivida ~30–40 h, prolongada si falla renal.","special":{"kind":"dose_cards","cards":[{"title":"Carga IV inicial","subtitle":"0,5 mg IV","copy":"Digoxina 0,5 mg IV, administración lenta conforme a ficha técnica, con control de ECG, FC, función renal y potasio."},{"title":"Carga IV adicional, si procede","subtitle":"0,25 mg IV a las 4–8 h","copy":"Digoxina 0,25 mg IV, solo tras reevaluar respuesta a la dosis previa, 4–8 h después; considerar carga total, edad, función renal y niveles."},{"title":"Mantenimiento oral (opciones)","choices":[{"label":"0,0625 mg/24 h","copy":"Digoxina 0,0625 mg VO cada 24 horas; comprobar presentación adecuada, función renal y niveles."},{"label":"0,125 mg/24 h","copy":"Digoxina 0,125 mg VO cada 24 horas; comprobar presentación, función renal y niveles."},{"label":"0,25 mg/24 h","copy":"Digoxina 0,25 mg VO cada 24 horas; controlar función renal, potasio y niveles cuando proceda."}]}],"sections":[{"title":"Farmacocinética clínica","text":"IV inicio 5–30 min, pico 1–5 h; VO inicio 30–120 min, pico 2–6 h. Semivida ~30–40 h, más prolongada en insuficiencia renal."},{"title":"Monitorización","text":"ECG/FC, clínica, función renal, Na/K/Mg y niveles plasmáticos en situaciones indicadas; extraer nivel en intervalo interpretable tras la dosis."},{"title":"Precauciones","text":"Margen terapéutico estrecho. Evitar en FA preexcitada. Atención a bradicardia, BAV, hipopotasemia e interacciones con amiodarona o verapamilo."}]},"diluent":"IV lento; dilución opcional según presentación y procedimiento local."},{"id":"dobutamina","name":"Dobutamina","brand":"Dobutamina · 250 mg/20 ml","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Concentrado de dobutamina 12,5 mg/ml. Ampolla/vial de 20 ml = 250 mg.","indication":"Bajo gasto cardíaco con hipoperfusión que requiere soporte inotrópico de inicio rápido, especialmente shock cardiogénico.","contraindication":"Hipersensibilidad, obstrucción mecánica del llenado o tracto de salida ventricular, hipovolemia sin corregir y arritmias ventriculares graves no controladas; consultar ficha según indicación.","precautions":"Precaución en hipotensión grave: puede disminuir la presión arterial por vasodilatación; si empeora, reevaluar dosis y situación hemodinámica. Riesgo de taquiarritmias e isquemia.","adverse":"Taquicardia, arritmias, dolor torácico, cambios tensionales e hipotensión.","administration":"Perfusión IV continua con bomba adecuada. Vía central preferente para concentraciones elevadas; valorar uso periférico únicamente con acceso adecuado, supervisión y protocolo local.","dosing":"Inicio orientativo 2–2,5 µg/kg/min; rango habitual 2,5–10 µg/kg/min. Titular según frecuencia cardíaca, presión arterial, gasto cardíaco y diuresis. Pueden requerirse dosis superiores en situaciones seleccionadas.","sources":[["Ficha técnica Dobutamina Hikma (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/85914/FT_85914.html"],["Ficha técnica Dobutamina Hospira (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/61952/FichaTecnica_61952.html"]],"notes":"Volúmenes finales, incluyendo el medicamento. Preparación concentrada: asegurar bomba adecuada y monitorización según protocolo.","dosingBrief":"Inicio orientativo: 2–2,5 µg/kg/min. Habitual: 2,5–10 µg/kg/min; titular según respuesta.","special":{"kind":"weight","doses":[2,2.5,4,6,8,10,12,15],"decimals":1,"preparations":[{"id":"dobu_1000_250","label":"1 g en 250 ml · Habitual","amountMg":1000,"volumeMl":250,"name":"1 g en 250 ml de SG 5 %","detail":"4 ampollas (80 ml de concentrado); completar hasta 250 ml finales."},{"id":"dobu_500_250","label":"500 mg en 250 ml","amountMg":500,"volumeMl":250,"name":"500 mg en 250 ml finales de SG 5 %","detail":"2 ampollas de 250 mg/20 ml (40 ml de concentrado); completar hasta 250 ml finales."},{"id":"dobu_250_250","label":"250 mg en 250 ml","amountMg":250,"volumeMl":250,"name":"250 mg en 250 ml de SG 5 %","detail":"1 ampolla (20 ml); completar hasta 250 ml finales."},{"id":"dobu_250_50","label":"250 mg en 50 ml · Bomba de jeringa","amountMg":250,"volumeMl":50,"name":"250 mg en 50 ml de SG 5 %","detail":"1 ampolla (20 ml); completar hasta 50 ml finales."}],"sections":[{"title":"Vía de administración y condiciones","text":"Perfusión IV continua mediante bomba. En concentraciones altas, vía central preferente. La administración periférica no está excluida de forma universal, pero depende de concentración, duración, calidad de la vía y protocolo local, con vigilancia estrecha del acceso."},{"title":"Ajustes renales y hepáticos","text":"Titular según respuesta clínica y hemodinámica; no aplicar una reducción fija por función renal o hepática. Mantener vigilancia estrecha en insuficiencia renal o hepática."},{"title":"Precauciones y contraindicaciones","text":"La hipotensión grave exige especial precaución: la dobutamina puede agravarla por vasodilatación. Revisar hipovolemia sin corregir, obstrucción mecánica significativa y arritmias graves. Vigilar isquemia miocárdica y taquiarritmias."},{"title":"Monitorización","text":"Igual esquema básico que dopamina: ECG, frecuencia cardíaca, presión arterial, diuresis, perfusión periférica y respuesta hemodinámica."},{"title":"Farmacocinética clínica","text":"Inicio IV en pocos minutos; el efecto hemodinámico se aprecia y titula rápidamente. Semivida plasmática aproximada 2 minutos; suele alcanzarse una respuesta estable tras unos 10 minutos a dosis constante. Reevaluar después de cada ajuste."}]},"clinicalKinetics":"Inicio IV en pocos minutos; el efecto hemodinámico se aprecia y titula rápidamente. Semivida plasmática aproximada 2 minutos; suele alcanzarse una respuesta estable tras unos 10 minutos a dosis constante. Reevaluar después de cada ajuste.","kineticsReviewed":true,"mechanism":"Agonista adrenérgico predominantemente β₁ (inotrópico).","diluent":"SG 5 % en las preparaciones seleccionadas."},{"id":"dopamina","name":"Dopamina","brand":"Dopamina · 200 mg/5 ml","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Dopamina 200 mg/5 ml; 40 mg/ml por ampolla.","indication":"Soporte hemodinámico en situaciones seleccionadas de shock o bajo gasto, bajo control clínico y monitorización apropiada.","contraindication":"Hipersensibilidad, feocromocitoma y taquiarritmias relevantes, incluidas ventriculares.","precautions":"Corregir hipovolemia antes o durante el soporte según el contexto. Vigilar arritmias, isquemia y extravasación. No utilizar dosis bajas para prevención o tratamiento de lesión renal aguda.","adverse":"Taquiarritmias, hipertensión o hipotensión, vasoconstricción e isquemia periférica, lesión por extravasación.","administration":"Perfusión IV continua con bomba, preferiblemente en vena de gran calibre y acceso adecuado; vigilar punto de inserción. La preparación seleccionada es concentrada: confirmar protocolo local.","dosing":"Inicio habitual 2–5 µg/kg/min, con titulación según respuesta hemodinámica. Mantenimiento habitual 5–20 µg/kg/min. El efecto dopaminérgico, beta y alfa es dosis-dependiente y sus rangos se solapan.","sources":[["Ficha técnica Dopamina Grifols (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/55454/FichaTecnica_55454.html"],["Guía NICE · lesión renal aguda","https://www.nice.org.uk/guidance/ng148/chapter/Recommendations"]],"notes":"No utilizar dopamina «a dosis renal» para prevención o tratamiento de lesión renal aguda. Las zonas coloreadas representan efectos farmacológicos predominantes, no seguridad ni indicación.","dosingBrief":"Inicio habitual: 2–5 µg/kg/min. Mantenimiento orientativo: 5–20 µg/kg/min, según respuesta.","special":{"kind":"weight","doses":[2,3,5,7.5,10,12,15,20],"decimals":2,"preparations":[{"id":"dopa_1000_250","label":"1 g en 250 ml · Habitual","amountMg":1000,"volumeMl":250,"name":"1 g en 250 ml de volumen final","detail":"5 ampollas de 200 mg/5 ml (25 ml de concentrado); completar hasta 250 ml finales de acuerdo con la preparación local."},{"id":"dopa_400_250","label":"400 mg en 250 ml","amountMg":400,"volumeMl":250,"name":"400 mg en 250 ml finales de SG 5 %","detail":"2 ampollas de 200 mg/5 ml (10 ml de concentrado); completar hasta 250 ml finales."}],"colorRanges":[{"label":"Dopaminérgico (D1/D2)","css":"dopaminergic","note":"aprox. 1–2 µg/kg/min"},{"label":"Predominio β₁","css":"beta","note":"aprox. 3–10 µg/kg/min"},{"label":"Predominio α₁","css":"alpha","note":"aprox. >10 µg/kg/min"}],"sections":[{"title":"Vía de administración y condiciones","text":"Perfusión IV continua mediante bomba. Vía venosa central preferente para estas concentraciones, con vigilancia estricta de extravasación e isquemia periférica. Las preparaciones concentradas deben ajustarse al protocolo local."},{"title":"Monitorización","text":"ECG continuo, FC, PA, diuresis, perfusión periférica, punto de infusión y respuesta hemodinámica."},{"title":"Ajustes renal y hepático","text":"Titular según respuesta clínica y hemodinámica. No existen reducciones porcentuales estándar establecidas para estas situaciones; vigilar respuesta y efectos adversos."},{"title":"Precauciones y contraindicaciones","text":"Corregir hipovolemia. Precaución ante taquiarritmias, cardiopatía isquémica e hipoperfusión periférica; riesgo de necrosis por extravasación. Contraindicada en feocromocitoma y taquiarritmias significativas."},{"title":"Interacciones","text":"Precaución con IMAO (fenelzina, tranilcipromina, selegilina), linezolid y anestésicos inhalatorios: pueden potenciar la respuesta presora o las arritmias. Los betabloqueantes pueden modificar la respuesta."},{"title":"Farmacocinética clínica","text":"Inicio de acción IV en unos 5 minutos; efecto clínico breve, aproximadamente 10 minutos tras detenerla. Semivida plasmática de unos 2 minutos. Titular con reevaluación hemodinámica frecuente."}]},"clinicalKinetics":"Inicio de acción IV en unos 5 minutos; efecto clínico breve, aproximadamente 10 minutos tras detenerla. Semivida plasmática de unos 2 minutos. Titular con reevaluación hemodinámica frecuente.","kineticsReviewed":true,"sourcesNotes":"El esquema concentrado de 1 g/250 ml requiere comprobación según protocolo local y condiciones de administración. La alternativa 400 mg/250 ml se ha incorporado como preparación adicional.","mechanism":"Agonista dopaminérgico y adrenérgico, con efectos dependientes de dosis.","diluent":"SG 5 % en las preparaciones seleccionadas."},{"id":"dronedarona","name":"Dronedarona","brand":"Multaq","group":"Arritmias y cardiovascular","routes":"VO","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Mantenimiento del ritmo sinusal después de cardioversión exitosa en fibrilación auricular paroxística o persistente, en pacientes seleccionados; no para FA permanente ni insuficiencia cardíaca descompensada.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false},{"id":"esmolol","name":"Esmolol","brand":"Brevibloc","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Bolsa lista para perfundir: 2.500 mg/250 ml, 10 mg/ml (Brevibloc 10 mg/ml). No confundir con concentrado 2.500 mg que exige dilución.","indication":"Control de frecuencia rápido y reversible en FA/flutter o taquicardia supraventricular seleccionada con monitorización.","dosingBrief":"Carga opcional: 500 µg/kg (0,5 mg/kg) IV en 1 min. Mantenimiento: empezar 50 µg/kg/min, titular a 100–200 µg/kg/min según respuesta. Preparación 10 mg/ml.","dosing":"Efecto en minutos, semivida breve ~9 min, reversibilidad clínica en torno a 30 min. La carga puede omitirse en pacientes con riesgo de hipotensión. No usar sin bomba y vigilancia.","administration":"Brevibloc 10 mg/ml listo para usar, perfusión IV con bomba. No mezclar con bicarbonato. Diferenciar preparación comercial diluida de ampolla concentrada.","contraindication":"Bradicardia grave, BAV avanzado, shock cardiogénico y descompensación de IC con bajo gasto; consultar ficha técnica.","precautions":"ECG continuo y PA frecuente; hipotensión y bradicardia requieren reducir o suspender.","adverse":"Hipotensión, bradicardia, bloqueo AV, insuficiencia cardíaca y reacción local.","notes":"La tabla de carga muestra mg y ml por peso (60–100 kg) y mantenimiento por peso; no asumir que un bolo rápido es apropiado para todos.","sources":[["AEMPS · Brevibloc 10 mg/ml","https://cima.aemps.es/cima/dochtml/ft/72608/FT_72608.html"]],"clinicalKinetics":"Inicio IV en minutos; semivida de eliminación ~9 minutos. El efecto beta bloqueante disminuye sustancialmente ~30 minutos tras suspender.","kineticsReviewed":true,"special":{"kind":"esmolol","sections":[{"title":"Farmacocinética clínica","text":"Inicio en minutos, semivida ~9 min y reversibilidad rápida tras interrupción."},{"title":"Vía y administración","text":"Bolsa lista para perfusión IV 2.500 mg/250 ml (10 mg/ml); bomba de precisión. Si se dispone de concentrado, exige dilución validada."},{"title":"Monitorización","text":"ECG y PA, FC, perfusión periférica y respuesta clínica."},{"title":"Precauciones","text":"Hipotensión, bradicardia, BAV, broncoespasmo; riesgo con otros bradicardizantes y bicarbonato incompatible."}]},"mechanism":"Antagonista β₁ de acción ultracorta.","diluent":"Brevibloc 10 mg/ml listo para usar: NO diluir."},{"id":"fenitoina","name":"Fenitoína","brand":"Fenitoína Rubio","group":"Neurología y reversión","routes":"IV, VO","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Tratamiento de crisis tónico-clónicas y focales y alternativa en estado epiléptico tras benzodiazepinas, bajo monitorización; tratamiento de algunas arritmias relacionadas con digitálicos según presentación/indicación.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"flecainida","name":"Flecainida","brand":"Apocard","group":"Arritmias y cardiovascular","routes":"IV, VO","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Prevención o conversión de determinadas arritmias supraventriculares en pacientes seleccionados sin cardiopatía estructural significativa; algunas arritmias ventriculares según indicación.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"flumazenilo","name":"Flumazenilo","brand":"Anexate / EFG","group":"Neurología y reversión","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Reversión parcial o completa de la sedación central por benzodiazepinas en pacientes seleccionados, especialmente procedimientos/anestesia; uso diagnóstico o en sobredosis con indicación cuidadosamente valorada.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"fosfato_iv","name":"Fosfatos IV","brand":"Fosfato monosódico / fosfato dipotásico 1 M","group":"Electrolitos y reposición","routes":"Perfusión IV","reviewed":true,"presentation":"Monosódico 1 M: ampolla 10 ml = 10 mmol de fosfato + 10 mEq de Na⁺. Dipotásico 1 M: ampolla 10 ml = 10 mmol de fosfato + 20 mEq de K⁺.","indication":"Reposición IV de fosfato en hipofosfatemia significativa, sintomática o cuando no es apropiada la vía oral. Preferir dipotásico si coexiste hipopotasemia; monosódico si K normal/alto, teniendo en cuenta sodio y función renal.","contraindication":"Ambas sales: insuficiencia renal grave e hiperfosfatemia. Dipotásico: hiperpotasemia. Monosódico: dieta de restricción de sodio (según FT). Ver FT para urolitiasis infecciosa y otras contraindicaciones.","precautions":"Controlar Ca (preferentemente ionizado cuando corresponda), P, K, Na, Mg, creatinina/FGe y diuresis. Hipocalcemia puede agravarse; hipercalcemia puede favorecer depósitos de fosfato cálcico y calcificaciones ectópicas (calcifilaxia en predispuestos). Ajustar si disfunción renal; evitar alto aporte de potasio o sodio.","adverse":"Hipocalcemia, hiperfosfatemia, hiperpotasemia con dipotásico, hipernatremia con monosódico, flebitis, calcificaciones ectópicas.","administration":"SIEMPRE perfusión IV previamente diluida con bomba; nunca en bolo. SF 0,9 % o SG 5 %, como diluyentes compatibles. Las concentraciones y acceso venoso deben validarse por Farmacia para cada sal; no mezclar con calcio ni con soluciones no compatibles. Preparaciones orientativas NO validadas para copia.","dosing":"También existen pautas fijas orientativas de 15 y 30 mmol para contextos seleccionados. No trasladar directamente los mismos tiempos a ambas sales: el dipotásico aporta 2 mEq de K por cada mmol de fosfato. Puede repetirse durante las primeras 48 horas según respuesta y analítica.","sources":[["AEMPS · Fosfato monosódico 1 M","https://cima.aemps.es/cima/dochtml/ft/63545/FichaTecnica_63545.html"],["AEMPS · Fosfato dipotásico 1 M","https://cima.aemps.es/cima/dochtml/ft/63546/FT_63546.html"],["EMCrit · Hypophosphatemia","https://emcrit.org/ibcc/hypophos/"]],"notes":"Los límites de 7,5 mmol P/h y 10/20 mEq K/h son umbrales conservadores de alerta, no pautas universales autorizadas. En cetoacidosis diabética, la ficha de dipotásico establece un máximo específico de 5 mEq K/h.","kineticsReviewed":false,"dosingBrief":"Inicio habitual: 0,08 mmol/kg durante 6 h en hipofosfatemia reciente no complicada. En otros casos individualizar (0,16 mmol/kg si prolongada; pautas alternativas 0,25 o 0,50 mmol/kg según fosfatemia).","diluent":"SF 0,9 % o SG 5 % para ambas sales. No utilizar Ringer ni Ringer Lactato con dipotásico; no añadir dobutamina a la misma solución."},{"id":"fosfatos_orales","name":"Fosfatos orales","brand":"Fosfato NM / solución de Joulie","group":"Electrolitos y reposición","routes":"VO","reviewed":true,"presentation":"Fosfato NM 3,56 g/sobre: 799 mg de fósforo (25,8 mmol de fosfato) y 25,8 mmol de Na. Solución de Joulie: fórmula magistral, concentración orientativa 1 mmol de fosfato/ml y 1 mEq de sodio/ml, según elaboración.","indication":"Fosfato NM: hipofosfatemia asociada a osteomalacia/raquitismo resistentes a vitamina D (indicación de FT). La reposición oral de hipofosfatemia hospitalaria requiere individualizar producto y pauta.","dosingBrief":"Fosfato NM: la FT indica 2–4 sobres/día para osteomalacia hipofosfatémica resistente a vitamina D, NO extrapolar automáticamente a reposición hospitalaria aguda. Solución de Joulie: 10/15/20 ml equivaldrían a 10/15/20 mmol si Farmacia confirma 1 mmol/ml.","dosing":"Disolver Fosfato NM en medio vaso de agua y administrar lentamente. Solicitar a Farmacia composición y concentración de cualquier solución magistral.","administration":"Vía oral. Fosfato NM disuelto en medio vaso de agua.","contraindication":"Hipersensibilidad; otras restricciones según formulación, función renal y electrolitos.","precautions":"Valorar hipernatremia, calcio, función renal, tolerancia digestiva y carga de sodio. No asumir equivalencia entre formulaciones orales.","adverse":"Molestias gastrointestinales, hiperfosfatemia y alteraciones de calcio/sodio.","sources":[["AEMPS · Fosfato NM","https://cima.aemps.es/cima/dochtml/ft/81120/FT_81120.html"]],"notes":"Preparaciones orales distintas de las concentradas IV."},{"id":"furosemida","name":"Furosemida","brand":"Seguril / EFG","group":"Arritmias y cardiovascular","routes":"IV, VO","reviewed":true,"presentation":"Ampolla 20 mg/2 ml (10 mg/ml); presentación de perfusión 250 mg/25 ml (10 mg/ml).","indication":"Congestión por insuficiencia cardíaca aguda o crónica; edema por enfermedad renal o hepática; edema agudo de pulmón y otras situaciones de sobrecarga hidrosalina con indicación de diuresis.","contraindication":"Anuria refractaria, hipovolemia grave y desequilibrios electrolíticos relevantes; confirmar ficha actual.","precautions":"Monitorizar PA, diuresis, balance hídrico, peso, Na/K/Cl/Mg, función renal y, si procede, gasometría venosa. Reponer K según analítica y función renal.","adverse":"Hipotensión, hipovolemia, trastornos hidroelectrolíticos, alcalosis metabólica, ototoxicidad con dosis altas/rápidas.","administration":"IV lenta, no superar 4 mg/min; en insuficiencia renal grave según FT (creatinina >5 mg/dl), 2,5 mg/min. Presentación de 250 mg/25 ml no es para bolo, solo perfusión controlada. SF 0,9 % diluyente adecuado; evitar medios ácidos.","dosing":"Respuesta insuficiente: valorar duplicar dosis IV y repetir según respuesta y plan de descongestión. Perfusión continua 250 mg/250 ml finales de SF 0,9 % (1 mg/ml). Suero salino hipertónico como protocolo seleccionado para congestión resistente, con validación local pendiente de mezclas.","sources":[["AEMPS · Furosemida Sala 250 mg/25 ml","https://cima.aemps.es/cima/dochtml/ft/65541/FichaTecnica_65541.html"],["SEMI · Protocolo manejo de IC aguda (2022)","https://www.fesemi.org/"],["NHS SPS · Administración IV","https://sps.nhs.uk/"]],"notes":"Sin tabla rígida de dosis según FGe: en insuficiencia renal pueden requerirse dosis mayores, titulando por congestión y respuesta. El suero hipertónico se reserva para casos seleccionados y debe validarse en Farmacia antes de su uso.","dosingBrief":"Sin tratamiento diurético previo: 20–40 mg IV iniciales. Con diurético de asa previo: considerar 1–2,5 veces la exposición diaria domiciliaria como pauta IV inicial, individualizar equivalencia. Reevaluar 2–6 h (diuresis y natriuresis).","kineticsReviewed":true,"clinicalKinetics":"Efecto IV en aproximadamente 5–15 minutos; duración clínica en horas, variable según función renal y estado de congestión.","special":{"kind":"furosemide","sections":[{"title":"Monitorización","text":"PA, FC, diuresis horaria, balance, peso, Na/K/Cl/Mg, función renal. Añadir gasometría venosa (pH, pCO₂ y HCO₃⁻) según evolución, especialmente por alcalosis metabólica."},{"title":"Ajustes y precauciones","text":"Titulación por congestión y diuresis/natriuresis, no por tabla rígida de FGe. Vigilar hipopotasemia y valorar reposición según K, filtrado y tratamiento concomitante."},{"title":"Farmacocinética clínica","text":"Inicio de efecto IV rápido, dentro de 5–15 min; duración variable de varias horas."},{"title":"Vía y condiciones","text":"SF 0,9 % adecuado para dilución. Soluciones ácidas pueden provocar precipitación. La presentación de 250 mg/25 ml es exclusiva para perfusión con bomba y tiene límite general de 4 mg/min (2,5 mg/min en insuficiencia renal grave con creatinina >5 mg/dl)."}]},"diluent":"SF 0,9 % en la perfusión seleccionada; el bolo IV puede administrarse sin diluir."},{"id":"glucagon","name":"Glucagón","brand":"GlucaGen HypoKit","group":"Metabolismo y otros","routes":"IM, SC, IV según producto","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Tratamiento de hipoglucemia grave cuando no es posible o está retrasada la administración IV de glucosa; uso seleccionado en intoxicación por betabloqueantes conforme a Toxicología.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"gluconato_calcico","name":"Gluconato cálcico","brand":"Suplecal Mini-Plasco","group":"Electrolitos y reposición","routes":"IV","reviewed":true,"presentation":"Ampolla de 10 ml: 940 mg de gluconato cálcico monohidrato + excipiente cálcico; calcio total 2,25 mmol (4,5 mEq) por ampolla.","indication":"Indicación autorizada: hipocalcemia aguda sintomática (tetania) y suplemento de calcio en nutrición parenteral. Uso en hiperpotasemia con cambios ECG o toxicidad por magnesio según protocolos de urgencia.","dosingBrief":"Hipocalcemia aguda: dosis inicial habitual 10 ml IV, repetir según clínica y calcio. En hiperpotasemia con alteraciones ECG utilizar el protocolo actualizado y confirmar concentración de la ampolla.","dosing":"Velocidades y dilución según ficha técnica del preparado y contexto. No sustituir mililitro a mililitro por cloruro cálcico.","administration":"IV lenta, diluida si procede según ficha. Verificar velocidad máxima de producto y permeabilidad venosa; riesgo de extravasación.","diluent":"SF 0,9 % o SG 5 % para perfusión según ficha técnica.","contraindication":"Hipercalcemia, tratamiento con glucósidos cardíacos en situaciones descritas por la ficha y otras contraindicaciones específicas.","precautions":"ECG y calcio ionizado cuando proceda; evitar extravasación e incompatibilidad con fosfatos o bicarbonato. No mezclar sin compatibilidad demostrada.","adverse":"Hipercalcemia, bradicardia/arritmias con administración rápida y lesión tisular por extravasación.","sources":[["AEMPS · Suplecal Mini-Plasco","https://cima.aemps.es/cima/dochtml/ft/69465/FichaTecnica_69465.html"]],"notes":"Calcio total de la ampolla: 2,25 mmol (incluye calcio del excipiente)."},{"id":"ferinject","name":"Hierro IV · Carboximaltosa férrica","brand":"Ferinject 50 mg/ml","group":"Hierro intravenoso","routes":"IV","reviewed":true,"presentation":"Ferinject: 50 mg de hierro/ml (p. ej., 500 mg/10 ml o 1.000 mg/20 ml).","indication":"Déficit de hierro confirmado cuando el hierro oral no es eficaz/no puede utilizarse o se requiere reposición rápida.","contraindication":"Hipersensibilidad al producto u otros hierros parenterales; anemia no debida a ferropenia; evidencia de sobrecarga de hierro (consultar FT).","precautions":"Administrar donde exista capacidad de tratar anafilaxia; observar al menos 30 min. Vigilar extravasación y fosfato en ciclos repetidos o factores de riesgo de hipofosfatemia. En hemodiálisis no exceder 200 mg/día en ≥14 años.","adverse":"Hipersensibilidad, náuseas, hipertensión, reacciones locales y posible hipofosfatemia/osteomalacia.","administration":"Solo IV: perfusión diluida exclusivamente en NaCl 0,9% o inyección IV. En perfusión: >200–500 mg, hasta 100 ml de SF en ≥6 min; >500–1.000 mg, hasta 250 ml de SF en ≥15 min. Confirmar tabla FT y concentración mínima.","dosing":"La necesidad total se determina por Hb y peso mediante la tabla oficial, no por fórmula de Ganzoni en esta ficha. En ≥14 años: máximo por administración 20 mg/kg IV en perfusión o 15 mg/kg en inyección, sin superar 1.000 mg; máximo 1.000 mg/semana, con ≥7 días entre dosis cuando sea necesaria una segunda. En hemodiálisis, máximo 200 mg/día.","dosingBrief":"≥14 años: perfusión hasta 20 mg/kg (máx. 1.000 mg), inyección hasta 15 mg/kg (máx. 1.000 mg); máximo semanal 1.000 mg.","sources":[["Ficha técnica Ferinject (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/69771/FichaTecnica_69771.html"]],"notes":"La calculadora usa la tabla oficial de necesidad total para ≥14 años; no sustituye confirmación analítica ni valoración de indicación. Vigilar hipofosfatemia en pacientes de riesgo.","kineticsReviewed":false,"diluent":"Perfusión: exclusivamente SF 0,9 %. Inyección IV: sin diluir."},{"id":"venofer","name":"Hierro IV · Sacarosa férrica","brand":"Venofer 20 mg/ml","group":"Hierro intravenoso","routes":"IV","reviewed":true,"presentation":"Venofer: 20 mg de hierro/ml; ampolla/vial de 5 ml = 100 mg.","indication":"Déficit de hierro confirmado, por ejemplo cuando se requiere aporte rápido o el hierro oral no es eficaz o tolerado.","contraindication":"Hipersensibilidad al producto u otros hierros parenterales; anemia sin ferropenia; sobrecarga férrica (consultar FT).","precautions":"Administrar con medios de tratamiento de anafilaxia y observar al menos 30 min. Cautela ante infección activa, sobrecarga de hierro y extravasación.","adverse":"Hipersensibilidad, hipotensión, náuseas, reacciones locales y alteraciones de tensión arterial.","administration":"Perfusión IV solo con NaCl 0,9%. Según FT: 100 mg diluidos como máximo en 100 ml en ≥15 min; 200 mg en máximo 200 ml en ≥30 min. Inyección lenta sin diluir: 1 ml/min, máx. 200 mg.","dosing":"La FT calcula la necesidad acumulada por fórmula de Ganzoni: peso(kg) × (Hb objetivo − Hb real)(g/dl) × 2,4 + depósitos de hierro. Si peso <35 kg, objetivo 13 g/dl y depósitos 15 mg/kg; si ≥35 kg, objetivo 15 g/dl y depósitos 500 mg. Dosis habitual adulta: 100–200 mg IV de 1 a 3 veces por semana.","dosingBrief":"Adultos: 100–200 mg IV por administración, 1–3 veces/semana; necesidad acumulada mediante Ganzoni.","sources":[["Ficha técnica Venofer (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/64000/"]],"notes":"No equiparar dosis única de sacarosa férrica con carboximaltosa. La calculadora estima déficit total, no pauta automática.","kineticsReviewed":false,"diluent":"Perfusión: exclusivamente SF 0,9 %. Inyección IV lenta: sin diluir."},{"id":"insulina_iv","name":"Insulina regular (perfusión)","brand":"Actrapid / Humulina Regular según producto","group":"Metabolismo y otros","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Control IV de hiperglucemia en cetoacidosis diabética, estado hiperosmolar y otros escenarios hospitalarios seleccionados, con protocolo y monitorización intensiva.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Pendiente: localizar y verificar el algoritmo SEMI para pacientes no críticos; no confundirlo con CAD/SHH ni con perfusión de UCI.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"isoprenalina","name":"Isoprenalina","brand":"Aleudrina","group":"Arritmias y cardiovascular","routes":"Perfusión IV","reviewed":true,"presentation":"Aleudrina 0,2 mg/ml, ampolla de 1 ml (0,2 mg = 200 µg).","indication":"Bradicardia grave/bloqueo AV como medida temporal con monitorización, en espera de estimulación cuando se indique.","dosingBrief":"Inicio de referencia: 2 µg/min; titular progresivamente hacia frecuencia cardíaca ~60 lpm y perfusión adecuada. Preparación seleccionada 1 mg/100 ml finales (10 µg/ml).","dosing":"Perfusión IV: inicio 2 µg/min, aumentando gradualmente hasta una frecuencia cardíaca aproximada de 60 lpm y respuesta hemodinámica adecuada. Uso temporal en entorno monitorizado.","administration":"5 ampollas (1 mg total) en 100 ml finales de SF 0,9 % = 10 µg/ml; perfusión con bomba y monitorización ECG/PA en área apropiada.","contraindication":"Taquiarritmias, arritmias ventriculares preexistentes, angina e infarto reciente, intoxicación digitálica. No administrar simultáneamente con adrenalina.","precautions":"Riesgo de taquiarritmias, isquemia e hipotensión por acción β₂; monitorizar ECG y respuesta.","adverse":"Taquicardia, arritmias, isquemia e hipotensión.","notes":"Dosis y preparación seleccionadas para revisión con el protocolo hospitalario. Precisa confirmación local antes de uso.","special":{"kind":"fixed_micro","doses":[2,3,4,5,6,8,10],"decimals":1,"preparations":[{"id":"iso_1_100","label":"1 mg en 100 ml · Habitual propuesta","amountMg":1,"volumeMl":100,"name":"1 mg en 100 ml finales de SF 0,9 %","detail":"5 ampollas de 0,2 mg/1 ml (5 ml de concentrado); completar hasta 100 ml finales."}],"sections":[{"title":"Vía y condiciones","text":"Perfusión IV continua con bomba de precisión en un entorno con ECG, PA y supervisión estrecha. Uso temporal, no sustituye el marcapasos cuando esté indicado."},{"title":"Precauciones y contraindicaciones","text":"Riesgo de taquiarritmias, isquemia e hipotensión. Contraindicada en angina, infarto reciente, arritmias ventriculares y taquiarritmias. No combinar simultáneamente con adrenalina."},{"title":"Monitorización","text":"ECG continuo, FC, PA, perfusión y respuesta clínica; titular hasta frecuencia adecuada sin inducir arritmia o hipotensión."},{"title":"Interacciones","text":"Evitar adrenalina concomitante y precaución con otros simpaticomiméticos, tricíclicos e IMAO."},{"title":"Farmacocinética clínica","text":"Respuesta cronotrópica IV rápida, susceptible de titulación en minutos. Disminución plasmática bifásica: semivida inicial ~5 min y fase posterior ~2,5 h; vigilar respuesta clínica, no el valor aislado."}]},"sources":[["AEMPS · Aleudrina concentrado 0,2 mg/ml (2026)","https://cima.aemps.es/cima/dochtml/ft/91119/FT_91119.html"],["AEMPS · Aleudrina solución inyectable","https://cima.aemps.es/cima/dochtml/ft/47131/FichaTecnica_47131.html"],["ERC 2025 · Soporte vital avanzado","https://www.erc.edu/media/vedoa2ga/gl2025-05-als-e.pdf"]],"clinicalKinetics":"Respuesta cronotrópica IV rápida, susceptible de titulación en minutos. Disminución plasmática bifásica: semivida inicial ~5 min y fase posterior ~2,5 h; vigilar respuesta clínica, no el valor aislado.","kineticsReviewed":true,"sourcesNotes":"La preparación de 1 mg/100 ml y la dosis inicial de 2 µg/min son las elegidas para el portal, pero difieren de la ficha técnica de Aleudrina concentrado de marzo 2026 (2 mg/500 ml, 0,01 µg/kg/min) y de la referencia de 5 µg/min en ERC 2025. Exigen validación local.","mechanism":"Agonista adrenérgico β₁ y β₂.","diluent":"SF 0,9 % en la preparación seleccionada; validar según presentación."},{"id":"labetalol","name":"Labetalol","brand":"Trandate / EFG","group":"Arritmias y cardiovascular","routes":"IV, VO","reviewed":true,"presentation":"Trandate 5 mg/ml: ampolla de 20 ml = 100 mg.","indication":"Hipertensión grave y crisis hipertensivas seleccionadas, incluida hipertensión del embarazo; control de presión arterial en contexto perioperatorio.","contraindication":"Bloqueo AV de segundo/tercer grado, shock cardiogénico, hipotensión o bradicardia grave, asma o enfermedad obstructiva de vías respiratorias; hipersensibilidad. Evitar en IAM con datos de bajo gasto y vasoconstricción periférica.","precautions":"Monitorizar PA/FC, bradicardia, broncoespasmo e hipotensión prolongada tras suspender. Precaución en insuficiencia cardíaca, hepatopatía y riesgo de lesión hepática.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Perfusión: 200 mg (40 ml de concentrado) en 200 ml finales de SG 5 % (1 mg/ml). Bolo IV lento sin dilución obligatoria; bomba para perfusión. Preparación institucional pendiente de validación.","dosing":"La hipotensión puede persistir varias horas tras detener la perfusión; detener al alcanzar objetivo, titular lentamente y controlar PA/FC.","sources":[["AEMPS · Trandate 5 mg/ml","https://cima.aemps.es/cima/dochtml/ft/55318/FT_55318.html"]],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"dosingBrief":"Bolo inicial de 20 mg IV en 2 min; repetir 20–40 mg cada 10 min según respuesta, hasta 200 mg acumulados. Perfusión: 200 mg en 200 ml finales de SG 5 % (1 mg/ml); 0,5–2 mg/min (30–120 ml/h).","diluent":"SG 5 % en la perfusión propuesta; en bolos IV lentos no precisa dilución obligatoria.","mechanism":"Antagonista α₁ y β-adrenérgico.","doseRows":[{"title":"Bolo IV lento","text":"20 mg durante 2 min; repetir 20–40 mg aproximadamente cada 10 min según PA hasta un máximo acumulado de 200 mg."},{"title":"Perfusión IV","text":"200 mg en 200 ml finales de SG 5 % (1 mg/ml). 0,5–2 mg/min (30–120 ml/h). Preparación local pendiente de validación."}]},{"id":"levetiracetam","name":"Levetiracetam","brand":"Keppra / EFG","group":"Neurología y reversión","routes":"IV, VO","reviewed":true,"presentation":"Keppra / Levetiracetam Hospira 100 mg/ml, vial 5 ml = 500 mg.","indication":"Control de epilepsia y sustitución temporal de vía oral cuando esta no sea viable.","contraindication":"Hipersensibilidad al levetiracetam u otros derivados de pirrolidona.","precautions":"Ajuste de dosis con función renal; vigilar alteraciones de comportamiento y somnolencia.","adverse":"Somnolencia, mareo, irritabilidad/alteraciones conductuales e hipersensibilidad.","administration":"","dosing":"Diluir la dosis en al menos 100 ml de SF 0,9%, SG5% o Ringer lactato; infundir durante 15 minutos según ficha del concentrado.\nConversión VO↔IV con la misma dosis total diaria y frecuencia. Las dosis de estatus epiléptico requieren protocolo específico no incorporado en esta revisión.","sources":[["Ficha técnica Levetiracetam Hospira (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/113889001/FT_113889001.html"]],"notes":"No convertir automáticamente dosis de mantenimiento en una dosis de carga de estatus.","dosingBrief":"IV: misma dosis diaria que VO; administrar en perfusión durante 15 min según ficha del concentrado.","kineticsReviewed":false,"diluent":"La preparación IV requiere confirmar la formulación; usar diluyente y volumen de la ficha técnica concreta."},{"id":"levosimendan","name":"Levosimendán","brand":"Simdax","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Vial 12,5 mg/5 ml (2,5 mg/ml). Diluyente: exclusivamente SG 5 %.","indication":"Descompensación aguda grave de IC crónica con necesidad de soporte inotrópico, especialmente en pacientes tratados con betabloqueantes y PA suficiente para tolerar vasodilatación.","contraindication":"ClCr <30 ml/min, insuficiencia hepática grave, hipotensión o taquicardia grave, obstrucción mecánica relevante y antecedentes de torsades de pointes.","precautions":"Hipotensión/vasodilatación, taquiarritmias, hipopotasemia. Corregir hipovolemia y K; monitorización durante y varios días después de perfusión.","adverse":"Hipotensión, taquicardia, cefalea, fibrilación auricular y reducción de potasio.","administration":"Perfusión IV con bomba, SG 5 % exclusivamente, vía periférica o central según tolerancia. Preparaciones a volumen FINAL, controlar necesidades para 24 h, estabilidad y apertura de bolsas.","dosing":"Reevaluar a los 30–60 min y tras ajustes: si hipotensión o taquicardia, disminuir a 0,05 µg/kg/min o suspender; si buena tolerancia y mayor efecto necesario, aumentar hasta 0,2 µg/kg/min. Si se necesitan >12,5 mg en total, preparar 10 ml (25 mg) en 500 ml finales SG 5 % (50 µg/ml), sin cambiar velocidad. Si >25 mg, se requiere planificación de otra preparación.","sources":[["AEMPS · Simdax, ficha técnica","https://cima.aemps.es/cima/dochtml/ft/64154/FichaTecnica_64154.html"],["Guía AEMPS / fabricante · preparación","https://cima.aemps.es/"]],"notes":"La pauta sin carga es una alternativa de práctica individualizada; cuando se decide dar carga, se ofrecen 6 o 12 µg/kg. No se incluye la dosis histórica de 24 µg/kg.","kineticsReviewed":true,"dosingBrief":"Preparación inicial única: 5 ml (12,5 mg) en 250 ml finales SG 5 % (50 µg/ml). Carga opcional 6 o 12 µg/kg IV durante 10 min; o inicio individualizado sin carga. Mantenimiento 0,1 µg/kg/min y ajuste 0,05–0,2 µg/kg/min durante 24 h.","clinicalKinetics":"Inicio hemodinámico durante la perfusión; semivida del fármaco ~1 h, metabolitos activos ~75–80 h. Efectos pueden persistir varios días tras suspender.","special":{"kind":"levosimendan","sections":[{"title":"Vía y condiciones","text":"Perfusión IV mediante bomba. Solo SG 5 %, preferiblemente control de presión y ECG. No mezclar con otros medicamentos fuera de compatibilidades verificadas."},{"title":"Farmacocinética clínica","text":"Semivida del fármaco ~1 h; metabolitos activos ~75–80 h, con efecto hemodinámico persistente varios días."},{"title":"Monitorización","text":"Previo: PA, FC, ECG, volemia, K y función renal/hepática. Durante: ECG, PA, FC, diuresis y K. Reevaluación a los 30–60 min y tras ajustar. Tras 24 h: vigilancia hemodinámica durante al menos 3 días (prolongar según función renal/hepática)."},{"title":"Contraindicaciones y precauciones","text":"Contraindicado en ClCr <30 ml/min, hepatopatía grave, hipotensión/taquicardia graves, obstrucción mecánica significativa y antecedente de torsades; vigilar hipopotasemia."}]},"mechanism":"Inodilatador sensibilizador al calcio.","diluent":"SG 5 % exclusivamente."},{"id":"manitol","name":"Manitol","brand":"Manitol 20%","group":"Electrolitos y soluciones","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Reducción aguda de presión intracraneal y edema cerebral en situaciones seleccionadas; reducción de presión intraocular en determinadas indicaciones.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"metoprolol","name":"Metoprolol","brand":"Beloken (tartrato)","group":"Arritmias y cardiovascular","routes":"IV, VO","reviewed":true,"presentation":"Solución inyectable 5 mg/5 ml (1 mg/ml). Comprimidos de metoprolol tartrato y liberación prolongada: no intercambiar formulaciones sin ajustar.","indication":"Control de frecuencia en FA/flutter o manejo de TSV seleccionadas en pacientes estables.","contraindication":"Bradicardia significativa, BAV avanzado, hipotensión, shock, IC aguda descompensada con bajo gasto; revisar FT.","precautions":"PA/FC/ECG. Evitar administración próxima a verapamilo IV y cautela con hipotensión.","adverse":"Hipotensión, bradicardia, bloqueo AV y broncoespasmo en predispuestos.","administration":"IV lento a 1–2 mg/min, sin dilución obligatoria; monitorizar ECG y PA.","dosing":"Dosis IV titulada según frecuencia y tolerancia. La continuación oral no es automática; distinguir tartrato de succinato de liberación prolongada.","sources":[["AEMPS · Beloken inyectable","https://cima.aemps.es/cima/dochtml/ft/56989/FT_56989.html"]],"notes":"Dosis máxima de referencia para pauta de control de frecuencia IV seleccionada 15 mg; no extrapolar a todas las indicaciones.","kineticsReviewed":false,"dosingBrief":"Inicio 2,5–5 mg IV a 1–2 mg/min, repetir si procede cada 5 min hasta una dosis acumulada habitual máxima de 15 mg. Si precisa tratamiento VO: metoprolol tartrato 25 o 50 mg cada 12 h, individualizar.","special":{"kind":"dose_cards","cards":[{"title":"Inicio IV · seleccionar","choices":[{"label":"2,5 mg","copy":"Metoprolol tartrato 2,5 mg IV a 1–2 mg/min, con ECG y PA."},{"label":"5 mg","copy":"Metoprolol tartrato 5 mg IV a 1–2 mg/min, con ECG y PA."}]},{"title":"Repetición IV","subtitle":"Cada 5 minutos si precisa; máximo acumulado 15 mg","copy":"Revalorar metoprolol IV cada 5 minutos según FC, PA y ECG; dosis acumulada habitual máxima de 15 mg."},{"title":"Tratamiento oral (tartrato) si indicado","choices":[{"label":"25 mg/12 h","copy":"Metoprolol tartrato 25 mg VO cada 12 horas, ajustar según FC/PA."},{"label":"50 mg/12 h","copy":"Metoprolol tartrato 50 mg VO cada 12 horas, ajustar según FC/PA."}]}],"sections":[{"title":"Vía y condiciones","text":"IV sin dilución obligatoria a 1–2 mg/min. Comprobar formulación oral (tartrato vs succinato retard)."},{"title":"Monitorización","text":"ECG, PA, FC, perfusión y signos de IC descompensada."},{"title":"Precauciones","text":"Evitar si hipotensión, BAV, shock o bajo gasto; precaución con verapamilo IV."}]},"diluent":"Bolo IV lento sin dilución obligatoria."},{"id":"naloxona","name":"Naloxona","brand":"Naloxona / EFG","group":"Neurología y reversión","routes":"IV, IM, IN según producto","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Reversión de depresión respiratoria por opioides en sobredosis o tras administración terapéutica; titular según ventilación y riesgo de resedación.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Pendiente: distinta estrategia en depresión respiratoria por opioides y reversión completa; riesgo de abstinencia precipitada.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"neostigmina","name":"Neostigmina","brand":"Prostigmina / EFG","group":"Neurología y reversión","routes":"IV, IM","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Reversión del bloqueo neuromuscular no despolarizante cuando corresponde, asociada a antimuscarínico; algunas indicaciones específicas para pseudoobstrucción colónica tras evaluación y monitorización.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"group":"Hipertensión y cardiovascular","reviewed":true,"notes":"Validar dilución local antes de utilizar una prescripción copiable.","id":"nicardipino","name":"Nicardipino","brand":"Vasonase","routes":"Perfusión IV","presentation":"1 mg/ml; ampolla de 10 ml = 10 mg.","mechanism":"Calcioantagonista dihidropiridínico arterial.","indication":"Hipertensión aguda potencialmente mortal, encefalopatía hipertensiva, disección aórtica combinada con control de frecuencia cuando corresponde, preeclampsia grave seleccionada e hipertensión postoperatoria.","dosingBrief":"Perfusión IV exclusiva: inicio 3–5 mg/h durante 15 min; aumentar 0,5–1 mg/h cada 15 min, máximo 15 mg/h. Al alcanzar objetivo, reducir a 2–4 mg/h.","dosing":"Control de PA/FC al menos cada 5 min durante perfusión y durante un mínimo de 12 h después de suspender, según ficha.","administration":"50 mg (50 ml de concentrado) en 250 ml finales de SF 0,9 % (0,2 mg/ml). Propuesta a validar con Farmacia. Sin bolos. Bomba de precisión, 5 mg/h =25 ml/h; máximo 15 mg/h=75 ml/h.","diluent":"SF 0,9 % o SG 5 % para dilución; concentración periférica 0,1–0,2 mg/ml.","contraindication":"Hipersensibilidad, estenosis aórtica grave e hipotensión grave; verificar lista de ficha técnica.","precautions":"Hipotensión y taquicardia refleja; precaución en insuficiencia cardíaca, disfunción hepática o renal y eventos coronarios. Reducir gradualmente; monitorización prolongada tras suspensión.","adverse":"Hipotensión, taquicardia, cefalea y flebitis.","sources":[["AEMPS · Vasonase","https://cima.aemps.es/cima/dochtml/ft/60975/FichaTecnica_60975.html"]],"doseRows":[{"title":"Perfusión IV exclusivamente","text":"50 mg en 250 ml finales de SF 0,9 % (0,2 mg/ml); comenzar 3–5 mg/h, titular 0,5–1 mg/h cada 15 min, máximo 15 mg/h. Preparación a validar."}]},{"id":"nimodipino","name":"Nimodipino","brand":"Nimotop / EFG","group":"Arritmias y cardiovascular","routes":"VO, IV según producto","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Prevención y tratamiento del déficit neurológico isquémico relacionado con vasoespasmo tras hemorragia subaracnoidea aneurismática, según vía y formulación.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Pendiente: comprobar formulación y vía, especialmente prohibición de administración IV de presentaciones orales.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"solinitrina_fuerte","name":"Nitroglicerina","brand":"Solinitrina Fuerte","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Solinitrina Fuerte 5 mg/ml; ampolla de 10 ml = 50 mg de nitroglicerina.","indication":"Dolor isquémico grave, insuficiencia ventricular izquierda aguda con congestión y determinadas crisis hipertensivas con descompensación cardíaca.","contraindication":"Hipotensión marcada o shock no controlado, uso reciente de inhibidores de PDE-5 o tratamiento con riociguat; comprobar otras contraindicaciones según situación clínica.","precautions":"Riesgo de hipotensión y cefalea. Considerar tolerancia con perfusiones prolongadas. Titular según presión arterial y respuesta clínica.","adverse":"Hipotensión, taquicardia refleja, cefalea, rubor y náuseas.","administration":"Perfusión IV continua mediante bomba. Usar SG 5 % para las preparaciones seleccionadas. Los volúmenes indicados son finales, incluida la ampolla.","dosing":"Inicio orientativo 10–20 µg/min con aumentos graduales de 10–20 µg/min cada 5–10 min según respuesta. Respuesta frecuente con 50–100 µg/min (3–6 mg/h). La tabla 1–6 mg/h solo convierte dosis a velocidad, no prescribe una pauta. Ajustar a situación y objetivo hemodinámico.","dosingBrief":"Inicio orientativo: 10–20 µg/min; titular según respuesta hemodinámica. Respuesta frecuente: 3–6 mg/h.","sources":[["Ficha técnica de Solinitrina Fuerte (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/57127/FT_57127.html"]],"notes":"Perfusión bajo monitorización hemodinámica. La concentración habitual del centro (200 µg/ml) difiere de la dilución de referencia de 100 µg/ml recogida en la ficha técnica.","special":{"kind":"fixed","doses":[1,2,3,4,5,6],"preparations":[{"id":"sol_200","label":"Habitual · 200 µg/ml","amountMg":50,"volumeMl":250,"name":"50 mg en 250 ml de SG 5 %","detail":"1 ampolla de 50 mg/10 ml; completar hasta 250 ml finales."},{"id":"sol_100","label":"Alternativa · 100 µg/ml","amountMg":50,"volumeMl":500,"name":"50 mg en 500 ml de SG 5 %","detail":"1 ampolla de 50 mg/10 ml; completar hasta 500 ml finales."}],"equivalent":"También puede prepararse con 100 mg en 500 ml de volumen final (2 ampollas): conserva la concentración de 200 µg/ml.","sections":[{"title":"Vía de administración y condiciones","text":"Perfusión IV continua mediante bomba, con titulación individualizada y monitorización hemodinámica. Verificar el dispositivo de perfusión y la preparación aplicada."},{"title":"Ajustes y precauciones","text":"En insuficiencia renal o hepática grave, titular con mayor vigilancia. Vigilar hipotensión; la respuesta puede disminuir con perfusiones prolongadas. Evitar reducción hemodinámica excesiva."},{"title":"Monitorización","text":"Presión arterial, frecuencia y ritmo cardíacos, dolor torácico, congestión y respuesta clínica."},{"title":"Interacciones y contraindicaciones","text":"No combinar con inhibidores de fosfodiesterasa tipo 5 (p. ej., sildenafilo, tadalafilo) ni con riociguat. Revisar estado hemodinámico y contraindicaciones según el paciente."},{"title":"Farmacocinética clínica","text":"Inicio de vasodilatación IV en pocos minutos; disminución rápida del efecto tras suspender la perfusión. Semivida plasmática breve (del orden de minutos). La respuesta depende de la dosis y del estado hemodinámico."}]},"clinicalKinetics":"Inicio de vasodilatación IV en pocos minutos; disminución rápida del efecto tras suspender la perfusión. Semivida plasmática breve (del orden de minutos). La respuesta depende de la dosis y del estado hemodinámico.","kineticsReviewed":true,"mechanism":"Vasodilatador nitrato, donador de óxido nítrico.","diluent":"SG 5 % en las preparaciones seleccionadas."},{"id":"noradrenalina","name":"Noradrenalina","brand":"Noradrenalina B. Braun 0,5 mg/ml (base)","group":"Arritmias y cardiovascular","routes":"IV","reviewed":true,"presentation":"Noradrenalina B. Braun 0,5 mg/ml (BASE), equivalente a 1 mg/ml de bitartrato. Ampolla de 10 ml: 5 mg base = 10 mg bitartrato. Vial de 50 ml: 25 mg base = 50 mg bitartrato.","indication":"Hipotensión aguda que requiere soporte vasopresor, tras evaluación de la causa y reposición apropiada.","contraindication":"Hipersensibilidad a componentes de la formulación; comprobar contraindicaciones concretas de la presentación utilizada. No confundir limitaciones de vía periférica con contraindicaciones absolutas.","precautions":"Corregir o abordar hipovolemia según contexto; vigilar perfusión periférica, isquemia y extravasación. El acceso periférico solo conforme a protocolo con seguimiento frecuente.","adverse":"Isquemia, hipertensión, bradiarritmia/arritmias y necrosis por extravasación.","administration":"Perfusión IV con bomba. Preparación de 10 o 20 mg BASE en 100 ml finales según protocolo local. Vía central preferente cuando corresponda; periférica solo en condiciones protocolizadas.","dosing":"Preparaciones seleccionadas: 10 mg BASE/100 ml finales (100 µg/ml) o 20 mg BASE/100 ml finales (200 µg/ml). Las dosis y conversiones siempre en BASE. Confirmar protocolo, diluyente y vía; SG 5 % preferente si corresponde.","sources":[["AEMPS · Noradrenalina B. Braun 0,5 mg/ml","https://cima.aemps.es/cima/dochtml/ft/62002/FT_62002.html"],["AEMPS · Cambio etiquetado noradrenalina (2022)","https://www.aemps.gob.es/informa/informacion-relevante-sobre-los-medicamentos-que-contienen-noradrenalina-norepinefrina/"],["SEFH · Infografía base/bitartrato","https://gruposdetrabajo.sefh.es/infografias/backend/pdfs/cambio_etiquetado_noradrenalina.pdf"]],"notes":"5 mg noradrenalina BASE = 10 mg bitartrato. La denominación del etiquetado cambió en 2022 sin alterar el contenido real. Preparación y compatibilidad sujetas a ficha y protocolo local.","dosingBrief":"Noradrenalina BASE: escoger 10 mg/100 ml (100 µg/ml) o 20 mg/100 ml (200 µg/ml), volúmenes FINALES. Tabla de velocidad por peso; titular según objetivos hemodinámicos.","special":{"kind":"noradrenaline","doses":[0.02,0.05,0.1,0.2,0.3,0.5,0.75,1],"decimals":2,"sections":[{"title":"Vía de administración y condiciones","text":"Perfusión IV continua mediante bomba de precisión y monitorización hemodinámica. Se prefiere acceso central según concentración, duración y protocolo local. Si se utiliza acceso periférico, hacerlo solo con protocolo específico y vigilancia estrecha de extravasación, punto de infusión y perfusión distal."},{"title":"Ajustes y precauciones","text":"Titular según respuesta hemodinámica y perfusión tisular, sin equivalencias fijas de dosis por función renal o hepática. Evaluar y corregir hipovolemia cuando corresponda. Riesgo de isquemia y extravasación; vigilar arritmias e hipertensión."},{"title":"Monitorización","text":"ECG, frecuencia cardíaca, presión arterial frecuente o continua según gravedad, perfusión periférica, diuresis, lactato cuando esté indicado y punto de infusión."},{"title":"Interacciones y contraindicaciones","text":"Revisar hipersensibilidad, interacciones con fármacos simpaticomiméticos, IMAO y antidepresivos tricíclicos, y riesgo de hipertensión o arritmias. Verificar contraindicaciones de la presentación utilizada."},{"title":"Farmacocinética clínica","text":"Inicio IV muy rápido, en segundos-minutos. Semivida plasmática breve, aproximadamente 1–2 minutos; el efecto presor suele desaparecer rápidamente al suspender la perfusión. Titular con monitorización continua."}]},"clinicalKinetics":"Inicio IV muy rápido, en segundos-minutos. Semivida plasmática breve, aproximadamente 1–2 minutos; el efecto presor suele desaparecer rápidamente al suspender la perfusión. Titular con monitorización continua.","kineticsReviewed":true,"mechanism":"Agonista adrenérgico predominantemente α₁, también β₁.","diluent":"SG 5 % (preferente según preparación); verificar formulación y protocolo local."},{"id":"pantoprazol","name":"Pantoprazol","brand":"Pantoprazol Normon / EFG","group":"Hemostasia y fibrinólisis","routes":"IV, VO","reviewed":true,"presentation":"Pantoprazol 40 mg polvo para solución IV (Normon/EFG).","indication":"Supresión ácida cuando la vía oral no es apropiada; indicaciones aprobadas según FT.","contraindication":"Hipersensibilidad a pantoprazol, benzimidazoles sustituidos o excipientes.","precautions":"Revisar interacciones, magnesio y necesidad de mantener IV. Reevaluar indicación.","adverse":"Flebitis local, cefalea, diarrea; problemas con uso prolongado.","administration":"FT: reconstituir 40 mg con 10 ml de SF 0,9%; directo o diluido en 100 ml de solución compatible y pasar en 2–15 min.","dosing":"Para HDA no varicosa de alto riesgo: el protocolo de 80 mg IV + 8 mg/h durante 72 h es un régimen de guías, NO posología autorizada específica de la FT seleccionada. Se dejará pendiente de validación separada antes de activar la plantilla.","sources":[["Ficha técnica Pantoprazol Normon (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/69698"]],"notes":"La perfusión de HDA se señala como pendiente de validación protocolaria, no como orden lista para prescribir.","dosingBrief":"HDA no varicosa de alto riesgo: 80 mg IV + 8 mg/h durante 72 h (régimen de guía, pendiente de validación local).","kineticsReviewed":false,"diluent":"Reconstituir con SF 0,9 %. Si se perfunde, diluir en SF 0,9 % o SG 5 % según ficha del producto."},{"id":"piridostigmina","name":"Piridostigmina","brand":"Mestinon","group":"Neurología y reversión","routes":"VO","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Tratamiento sintomático de la miastenia gravis; otras indicaciones según presentación aprobada.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false},{"id":"prasugrel","name":"Prasugrel","brand":"Efient / EFG","group":"Hemostasia y fibrinólisis","routes":"VO","reviewed":true,"presentation":"Efient / EFG, comprimidos 5 y 10 mg.","indication":"Prevención de eventos aterotrombóticos en SCA sometido a ICP, asociado a AAS.","contraindication":"Ictus o AIT previo, hemorragia patológica activa y hepatopatía grave, según FT.","precautions":"Edad avanzada y peso <60 kg elevan riesgo de sangrado; considerar restricciones y momento de carga en SCASEST.","adverse":"Hemorragia, anemia y reacciones de hipersensibilidad.","administration":"","dosing":"VO; dosis de carga única 60 mg y después 10 mg/24 h. En peso <60 kg: mantenimiento 5 mg/24 h, según FT.\nNo administrar carga indiscriminada antes de conocer anatomía coronaria en determinados SCASEST.","sources":[["Ficha técnica Efient 5 mg (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/08503002/FT_08503002.html"]],"notes":"Comprobar antecedentes de ictus/AIT antes de considerar este antiagregante.","dosingBrief":"SCA: carga 60 mg VO; mantenimiento 10 mg/24 h (5 mg/24 h si peso <60 kg, según ficha).","kineticsReviewed":false},{"id":"propofol","name":"Propofol","brand":"Diprivan / EFG","group":"Neurología y reversión","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Inducción y mantenimiento de anestesia general; sedación durante procedimientos o en pacientes ventilados en UCI bajo condiciones autorizadas y monitorización especializada.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"remifentanilo","name":"Remifentanilo","brand":"Ultiva / EFG","group":"Neurología y reversión","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Analgesia en anestesia general y pacientes seleccionados ventilados en UCI; uso exclusivo en entorno con medios de control respiratorio.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"rocuronio","name":"Rocuronio","brand":"Esmeron / EFG","group":"Neurología y reversión","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Bloqueo neuromuscular para facilitar intubación traqueal y durante anestesia o ventilación mecánica, bajo sedoanalgesia adecuada.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"somatostatina","name":"Somatostatina","brand":"Somatostatina / EFG","group":"Hemostasia y fibrinólisis","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Tratamiento adyuvante de hemorragia digestiva por hipertensión portal/varices en situaciones seleccionadas y otras indicaciones específicas según presentación.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Pendiente: diferenciar usos en hemorragia varicosa y otras indicaciones; verificar presentación y dilución.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"succinilcolina","name":"Succinilcolina","brand":"Anectine / EFG","group":"Neurología y reversión","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Relajación muscular rápida para intubación y procedimientos anestésicos seleccionados en pacientes apropiados.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"sugammadex","name":"Sugammadex","brand":"Bridion / EFG","group":"Neurología y reversión","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Reversión de bloqueo neuromuscular inducido por rocuronio o vecuronio, ajustada al nivel de bloqueo.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Ficha reservada: requiere revisión individual antes de uso asistencial.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"magnesio_iv","name":"Sulfato de magnesio","brand":"Sulfato de magnesio","group":"Electrolitos y soluciones","routes":"IV","reviewed":true,"presentation":"EXCLUSIVAMENTE ampolla de 1,5 g/10 ml (150 mg/ml de sulfato de magnesio; aprox. 6,1 mmol de Mg por ampolla).","indication":"Torsades de pointes, hipomagnesemia que precisa IV y coadyuvante en exacerbación asmática grave seleccionada.","contraindication":"Insuficiencia renal grave, bloqueo AV significativo, miastenia gravis y otras contraindicaciones de FT según indicación.","precautions":"Acumulación en insuficiencia renal; vigilar PA, función respiratoria, reflejos, calcemia y potasio.","adverse":"Hipotensión, rubor, hiporreflexia, depresión respiratoria, bradicardia/bloqueo AV.","administration":"Compatible con SF 0,9 % o SG 5 % según producto. Las velocidades urgentes dependen del contexto; monitorizar PA, ECG si indicado, reflejos y respiración en dosis elevadas.","dosing":"No intercambiar gramos de sulfato con mmol de magnesio elemental. En hipomagnesemia <1,2 mg/dl o sintomática pueden precisarse dosis repetidas o perfusión monitorizada; individualizar, sobre todo en insuficiencia renal.","sources":[["AEMPS · Sulfato de magnesio 1,5 g/10 ml","https://cima.aemps.es/cima/dochtml/ft/78350/FT_78350.html"],["EMCrit · Hypomagnesemia","https://emcrit.org/ibcc/hypomagnesemia/"],["NHS SPS · Acute hypomagnesaemia","https://sps.nhs.uk/articles/treating-acute-hypomagnesaemia-in-adults/"]],"notes":"Pauta simplificada de 3 g para reposición IV no urgente dentro de un rango orientativo de 2–4 g; no extrapolar automáticamente a hipomagnesemia grave con convulsiones o arritmias.","kineticsReviewed":false,"dosingBrief":"Torsades: 2 g IV (13,3 ml de concentrado), según protocolo de reanimación. Hipomagnesemia no urgente: 3 g IV (20 ml; 2 ampollas) en perfusión lenta, individualizar. Asma grave seleccionada: 2 g IV en 20 min. Solo ampollas de 1,5 g.","special":{"kind":"dose_cards","cards":[{"title":"Torsades de pointes","subtitle":"2 g IV (13,3 ml del concentrado)","copy":"Sulfato de magnesio 2 g IV (13,3 ml de 150 mg/ml), según protocolo de torsades y situación hemodinámica, con ECG continuo."},{"title":"Hipomagnesemia · reposición no urgente","subtitle":"3 g IV (20 ml = 2 ampollas) en perfusión lenta","copy":"Sulfato de magnesio 3 g IV (2 ampollas de 1,5 g/10 ml), diluir en 100 ml finales de SF 0,9 % y perfundir en 2 horas (50 ml/h). Reevaluar Mg, K y función renal."},{"title":"Exacerbación asmática grave seleccionada","subtitle":"2 g IV en 20 minutos","copy":"Sulfato de magnesio 2 g IV (13,3 ml de concentrado) en 100 ml finales de SF 0,9 % durante 20 minutos (300 ml/h), como coadyuvante en asma grave seleccionada."}],"sections":[{"title":"Monitorización","text":"PA, ionograma (Mg/Ca/K), función renal; ECG en arritmias/síntomas graves y reflejos/respiración si dosis altas."},{"title":"Precauciones","text":"Ajuste cuidadoso en FGe <30 ml/min; riesgo de acumulación e hipermagnesemia. En toxicidad grave valorar gluconato cálcico IV."},{"title":"Farmacocinética clínica","text":"Efecto IV rápido. Eliminación renal; acumulación en disfunción renal."},{"title":"Vía y condiciones","text":"SF 0,9 % o SG 5 % según ficha del producto. En torsades, velocidad según contexto de reanimación; no equivale a perfusión de reposición lenta."}]},"diluent":"SF 0,9 % o SG 5 %, según preparación y velocidad."},{"id":"tenecteplasa","name":"Tenecteplasa","brand":"Metalyse (presentación según indicación)","group":"Hemostasia y fibrinólisis","routes":"IV","reviewed":true,"presentation":"Metalyse 25 mg (ictus) y presentaciones de 40–50 mg (IAM). La concentración reconstituida y el vial dependen de la indicación.","indication":"Trombólisis de ictus isquémico agudo e IAM con elevación del ST, con productos y criterios de elegibilidad diferenciados.","contraindication":"Riesgo de hemorragia, hemorragia intracraneal y contraindicaciones por indicación/tiempo; revisar ficha.","precautions":"Verificar primero ICTUS vs IAM, producto específico, peso, edad, momento de inicio y criterios de selección; monitorización obligada.","adverse":"Hemorragia grave, incluida intracraneal, y reperfusión/arritmias según patología.","administration":"Bolo IV único según banda de peso e indicación. Reconstitución según envase de Metalyse concreto.","dosing":"Ictus: bandas 15–25 mg (máx. 25 mg) con vial de 25 mg. IAM: bandas 30–50 mg (máx. 50 mg) con presentación de IAM. No intercambiar.","sources":[["Ficha técnica Metalyse ictus 25 mg (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/1000169007/FT_1000169007.html"],["Ficha técnica Metalyse IAM 50 mg (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/00169006/FT_00169006.html"]],"notes":"ALERTA: las bandas de peso y viales para ictus e infarto son diferentes.","dosingBrief":"Ictus: bolo IV por bandas 15–25 mg; IAM: 30–50 mg. Elegir formulación según indicación.","kineticsReviewed":false,"diluent":"Reconstituir exclusivamente con el disolvente del envase; no confundir productos ni pautas de ictus e IAM."},{"id":"terlipresina","name":"Terlipresina","brand":"Glypressin / EFG","group":"Hemostasia y fibrinólisis","routes":"IV","reviewed":false,"presentation":"Pendiente de comprobar presentación y disponibilidad local.","indication":"Tratamiento de hemorragia variceal aguda y síndrome hepatorrenal seleccionado, siguiendo criterios y vigilancia específicos.","contraindication":"Pendiente de cotejo con ficha técnica.","precautions":"Pendiente de cotejo con ficha técnica y protocolo del centro.","adverse":"Pendiente de cotejo con ficha técnica.","administration":"Pendiente de validar vía, dilución, concentración, estabilidad y velocidad.","dosing":"No hay pauta validada en esta edición. No utilizar el prontuario histórico como orden de prescripción.","sources":[],"notes":"Pendiente: advertencias vasculares y respiratorias, y diferencias de pauta entre hemorragia varicosa y síndrome hepatorrenal.","kineticsReviewed":false,"diluent":"Pendiente de verificar diluyentes, concentración y vía con la ficha técnica de la presentación concreta."},{"id":"ticagrelor","name":"Ticagrelor","brand":"Brilique / EFG","group":"Hemostasia y fibrinólisis","routes":"VO","reviewed":true,"presentation":"Brilique 90 mg y 60 mg (según pauta).","indication":"SCA y prevención prolongada de eventos aterotrombóticos en pacientes seleccionados.","contraindication":"Hemorragia patológica activa, antecedente de hemorragia intracraneal, hepatopatía grave; revisar interacciones.","precautions":"Disnea, bradiarritmias, riesgo de sangrado, interacción con inhibidores/inductores de CYP3A4.","adverse":"Hemorragia, disnea, bradicardia y aumento de ácido úrico.","administration":"Vía oral.","dosing":"SCA: carga 180 mg y mantenimiento 90 mg cada 12 h; prolongación seleccionada >1 año: 60 mg cada 12 h, con condiciones.\nAcompañar AAS dosis baja salvo circunstancias específicas del tratamiento antiagregante.","sources":[["Ficha técnica Brilique 90 mg (AEMPS)","https://cima.aemps.es/cima/dochtml/ft/110655013/FT"]],"notes":"Confirmar estrategia de doble antiagregación y duración con indicación.","dosingBrief":"SCA: carga 180 mg VO; después 90 mg/12 h. Prolongación seleccionada: 60 mg/12 h.","kineticsReviewed":false},{"group":"Hipertensión y cardiovascular","reviewed":true,"notes":"Validar dilución local antes de utilizar una prescripción copiable.","id":"urapidilo","name":"Urapidil","brand":"Urapidil Accord / Kalceks","routes":"IV","presentation":"5 mg/ml; ampolla de 10 ml = 50 mg.","mechanism":"Antagonista α₁ periférico y agonista 5-HT1A central.","indication":"Crisis hipertensivas; control de hipertensión perioperatoria y protección frente a aumentos tensionales durante maniobras anestésicas.","dosingBrief":"Bolo inicial 25 mg IV lento; reevaluar y repetir 25 mg si procede; posteriormente 50 mg según respuesta. Perfusión seleccionada 250 mg en 250 ml finales (1 mg/ml), comenzar aproximadamente 5 mg/h y titular; mantenimiento orientativo 9 mg/h.","dosing":"Titulación por respuesta y PA; las pautas de perfusión propuestas requieren validación de Farmacia.","administration":"Bolo IV lento. Perfusión propuesta: 250 mg (50 ml de concentrado) hasta 250 ml finales de SF 0,9 %, 1 mg/ml, con bomba.","diluent":"SF 0,9 % o SG 5 % según ficha y preparación.","contraindication":"Hipersensibilidad; evitar en coartación aórtica y determinadas comunicaciones arteriovenosas hemodinámicamente relevantes.","precautions":"Hipotensión, especialmente en ancianos, hipovolemia y disfunción renal/hepática; monitorizar PA y FC. Duración parenteral limitada según ficha.","adverse":"Hipotensión, cefalea, mareos y náuseas.","sources":[["AEMPS · Urapidil Accord","https://cima.aemps.es/cima/dochtml/ft/76741/FichaTecnica_76741.html"],["AEMPS · Urapidil Kalceks","https://cima.aemps.es/cima/dochtml/ft/85873/FT_85873.html"]],"doseRows":[{"title":"Bolo IV inicial","text":"25 mg IV lento; reevaluar y considerar 25 mg adicionales; después 50 mg si procede."},{"title":"Perfusión IV","text":"250 mg en 250 ml finales de SF 0,9 % (1 mg/ml); inicio orientativo 5 mg/h, titular según PA. Preparación pendiente de validación."}]},{"id":"verapamilo","name":"Verapamilo","brand":"Manidón","group":"Arritmias y cardiovascular","routes":"IV, VO","reviewed":true,"presentation":"Ampolla 5 mg/2 ml (2,5 mg/ml). Comprimidos de liberación prolongada 120/240 mg según producto.","indication":"Taquicardia supraventricular regular estable y control de frecuencia en FA/flutter sin preexcitación y con FEVI >40 % en casos seleccionados.","dosingBrief":"Inicio IV 2,5 o 5 mg durante unos 5 min (seleccionar dosis). Puede valorarse repetir hasta 10 mg después de 30 min si procede. VO retard 120 o 240 mg/24 h según indicación, no automático.","dosing":"Controlar PA/ECG/FC. No combinar cercanamente con betabloqueantes IV; evitar en disfunción sistólica significativa, hipotensión, BAV o FA preexcitada.","contraindication":"Hipotensión, shock, BAV avanzado, insuficiencia ventricular significativa, FA/flutter con preexcitación, combinación temporal con beta bloqueantes IV.","precautions":"La administración IV debe ser lenta, con monitorización ECG y PA. Cautela por bradicardia e hipotensión.","adverse":"Hipotensión, bradicardia, bloqueo AV, estreñimiento y empeoramiento de IC sistólica.","administration":"Administrar IV lentamente, sin dilución obligatoria para la presentación inyectable; controlar ECG y PA.","sources":[["AEMPS · Manidón inyectable","https://cima.aemps.es/cima/dochtml/ft/39784/FichaTecnica_39784.html"]],"notes":"La continuación por vía oral solo está indicada cuando persiste una indicación, no tras cualquier TSV autolimitada.","clinicalKinetics":"IV: inicio de efecto en pocos minutos; monitorizar PA y conducción desde la administración.","kineticsReviewed":true,"special":{"kind":"dose_cards","cards":[{"title":"Primera dosis IV · seleccionar","choices":[{"label":"2,5 mg","copy":"Verapamilo 2,5 mg IV lento, durante 5 min, sin dilución obligatoria; monitorizar ECG y PA."},{"label":"5 mg","copy":"Verapamilo 5 mg IV lento, durante 5 min, sin dilución obligatoria; monitorizar ECG y PA."}]},{"title":"Reevaluación a 30 minutos","subtitle":"Hasta 10 mg IV si se precisa","copy":"Verapamilo 10 mg IV lento tras al menos 30 min y reevaluación clínica, solo si procede; monitorizar ECG y PA."},{"title":"Continuación oral, si indicada","choices":[{"label":"120 mg retard/24 h","copy":"Verapamilo liberación prolongada 120 mg VO cada 24 horas, según indicación y tolerancia."},{"label":"240 mg retard/24 h","copy":"Verapamilo liberación prolongada 240 mg VO cada 24 horas, según indicación y tolerancia."}]}],"sections":[{"title":"Monitorización","text":"ECG, FC y PA durante y tras la administración IV."},{"title":"Precauciones","text":"Evitar en FA preexcitada, FEVI ≤40 %, hipotensión, BAV y combinación temporal con betabloqueantes IV."}]},"diluent":"Bolo IV lento sin dilución obligatoria."}];
